```java
public interface RefundPolicy {
    RefundQuote quote(List<BookingSeat> seatsToCancel, Duration timeBeforeShow);
}

final class SlabRefundPolicy implements RefundPolicy {
    private final List<Slab> slabsDescending;          // (24,100) (4,50) (0,0)
    private final boolean refundFees;

    public RefundQuote quote(List<BookingSeat> seats, Duration before) {
        long hours = before.toHours();                  // 23h59m counts as 23
        int percent = slabsDescending.stream()
                .filter(s -> hours >= s.minHoursBefore())
                .findFirst().map(Slab::percent).orElse(0);
        return RefundMath.quote(seats, percent, refundFees);
    }
}

final class RefundMath {
    static RefundQuote quote(List<BookingSeat> seats, int percent, boolean refundFees) {
        long ticket = seats.stream().mapToLong(s -> s.amountPaise() - s.feePaise()).sum();
        long fees   = seats.stream().mapToLong(BookingSeat::feePaise).sum();
        long refund = Money.ofPaise(ticket).percent(percent).paise() + (refundFees ? fees : 0);
        return new RefundQuote(percent, refund, ticket + fees - refund);
    }
}

@Component
class RefundPolicyResolver {
    RefundPolicy resolve(RefundPolicySnapshot snapshot, CancellationReason reason) {
        if (reason == CancellationReason.SHOW_CANCELLED) return new FullRefundPolicy();   // always 100%
        return switch (snapshot.type()) {       // the one switch; the compiler flags a missing case
            case SLAB           -> new SlabRefundPolicy(snapshot.slabs(), snapshot.refundFees());
            case FULL           -> new FullRefundPolicy();
            case NON_REFUNDABLE -> new NonRefundablePolicy();
        };
    }
}
```

