    if (body instanceof ProblemDetail problem && !hasCode(problem)) {
        if (statusCode.isSameCodeAs(ErrorCode.VALIDATION_FAILED.status())) {
            problem.setProperty(CODE, ErrorCode.VALIDATION_FAILED.name());
