        assertThat(createdBy).isEqualTo(ADMIN_ID);
    }

    @Test
    void cityNamesAreUniqueIgnoringCase() throws Exception {
        String name = uniqueName("Delhi");
        createCity(name);

        mvc.perform(asAdmin(post("/api/v1/admin/cities")).content(cityJson(name.toUpperCase())))
