    @Test
    void rejectsUnknownTimezoneAndBlankName() throws Exception {
        mvc.perform(asAdmin(post("/api/v1/admin/cities"))
                        .content("""
                                {"name": "%s", "timezone": "Mars/Olympus"}
                                """.formatted(uniqueName("Goa"))))
