        assertThat(seat(plan, "B1")).extracting(LayoutPlan.Seat::gridRow, LayoutPlan.Seat::gridCol).containsExactly(2, 2);
        assertThat(seat(plan, "B1").categoryCode()).isEqualTo("PREMIUM");
        assertThat(plan.seats()).hasSize(11);
