public class Show extends AuditedEntity {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    private Long movieId;

    private Long screenId;

    private Long theaterId;

    private Long cityId;

    private Long layoutId;

