    void createsACouponWithScopes() throws Exception {
        create("""
                {"code": "%s", "discountType": "FLAT", "discountValue": 5000, "minOrderPaise": 30000,
                 "validFrom": "2026-10-01T00:00:00+05:30", "validTo": "2026-10-31T23:59:59+05:30",
