        return """
                {"code": "%s", "discountType": "FLAT", "discountValue": 5000,
                 "validFrom": "2026-10-01T00:00:00Z", "validTo": "2026-12-31T00:00:00Z", "maxUses": 100, "scopes": []}
                """.formatted(code);
    }
