    void luhn() {
        assertThat(CardPaymentProcessor.passesLuhn("4242424242424242")).isTrue();
        assertThat(CardPaymentProcessor.passesLuhn("5555555555554444")).isTrue();
        assertThat(CardPaymentProcessor.passesLuhn("4242424242424241")).isFalse();
    }

