package com.sumit.movieticketbookingsystem.booking;

import com.jayway.jsonpath.JsonPath;
import com.sumit.movieticketbookingsystem.MutableClock;
import com.sumit.movieticketbookingsystem.MutableClockConfiguration;
import com.sumit.movieticketbookingsystem.TestcontainersConfiguration;
import com.sumit.movieticketbookingsystem.booking.BookingFixtures.BookableShow;
import com.sumit.movieticketbookingsystem.pricing.CouponFixtures;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;
import org.springframework.context.annotation.Import;
import org.springframework.jdbc.core.simple.JdbcClient;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.test.web.servlet.ResultActions;

import java.time.Duration;
import java.time.Instant;
import java.util.UUID;

import static com.sumit.movieticketbookingsystem.ApiRequests.asCustomer;
import static org.assertj.core.api.Assertions.assertThat;
import static org.hamcrest.Matchers.contains;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

@SpringBootTest
@AutoConfigureMockMvc
@Import({TestcontainersConfiguration.class, MutableClockConfiguration.class})
class CheckoutIT {

    private static final String UPI = """
            {"type": "UPI", "vpa": "asha@okbank"}""";

    @Autowired
    private MockMvc mvc;

    @Autowired
    private JdbcClient jdbc;

    @Autowired
    private MutableClock clock;

    private BookableShow show;
    private UUID customer;

    @BeforeEach
    void setUp() throws Exception {
        show = new BookingFixtures(mvc, jdbc).openShow();
        customer = UUID.randomUUID();
    }

    @AfterEach
    void resetClock() {
        clock.reset();
    }

    @Test
    void successfulPaymentConfirmsTheBooking() throws Exception {
        String code = new CouponFixtures(mvc).coupon("\"discountType\": \"FLAT\", \"discountValue\": 1000");
        String bookingId = hold(code, "A1", "A2");

        pay(bookingId, UPI, "SUCCESS", UUID.randomUUID())
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.paymentStatus").value("SUCCESS"))
                .andExpect(jsonPath("$.booking.status").value("CONFIRMED"));

        mvc.perform(asCustomer(get("/api/v1/shows/{id}/seats", show.id())))
                .andExpect(jsonPath("$.seats[?(@.label == 'A1')].status").value(contains("BOOKED")))
                .andExpect(jsonPath("$.seats[?(@.label == 'A2')].status").value(contains("BOOKED")));
        assertThat(jdbc.sql("SELECT status FROM coupon_redemption WHERE booking_id = ?")
                .param(UUID.fromString(bookingId)).query(String.class).single()).isEqualTo("CONSUMED");
        assertThat(jdbc.sql("SELECT masked_details FROM payment WHERE booking_id = ? AND status = 'SUCCESS'")
                .param(UUID.fromString(bookingId)).query(String.class).single()).isEqualTo("asha@okbank");
    }

    @Test
    void declinedPaymentGivesTheSeatsAndCouponBack() throws Exception {
        String code = new CouponFixtures(mvc).coupon("\"discountType\": \"FLAT\", \"discountValue\": 1000");
        String bookingId = hold(code, "B1");

        pay(bookingId, UPI, "FAILURE", UUID.randomUUID())
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.paymentStatus").value("FAILED"))
                .andExpect(jsonPath("$.failureReason").value("Declined by issuer (simulated)"))
                .andExpect(jsonPath("$.booking.status").value("FAILED"));

        assertThat(seatStatus("B1")).isEqualTo("AVAILABLE");
        assertThat(jdbc.sql("SELECT used_count FROM coupon WHERE code = ?").param(code).query(Integer.class).single())
                .isZero();
        hold(code, "B1");                                         // the customer can simply try again
    }

    @Test
    void invalidPaymentDetailsLeaveTheHoldAsItWas() throws Exception {
        String bookingId = hold(null, "A3");

        pay(bookingId, """
                {"type": "CARD", "number": "4242 4242 4242 4241", "expiryMonth": 12, "expiryYear": 2030,
                 "cvv": "123", "holderName": "Asha"}""", "SUCCESS", UUID.randomUUID())
                .andExpect(status().isBadRequest())
                .andExpect(jsonPath("$.detail").value("The card number isn't valid"));
        mvc.perform(asCustomer(get("/api/v1/bookings/{id}", bookingId), customer))
                .andExpect(jsonPath("$.status").value("HELD"));

        pay(bookingId, """
                {"type": "CARD", "number": "4242 4242 4242 4242", "expiryMonth": 12, "expiryYear": 2030,
                 "cvv": "123", "holderName": "Asha"}""", "SUCCESS", UUID.randomUUID())
                .andExpect(jsonPath("$.booking.status").value("CONFIRMED"));
    }

    @Test
    void startingPaymentLateStillLeavesTimeToFinish() throws Exception {
        String bookingId = hold(null, "A4");
        clock.advance(Duration.ofMinutes(6));                     // 2 of the 8 minutes left

        String response = pay(bookingId, UPI, "SUCCESS", UUID.randomUUID())
                .andExpect(jsonPath("$.booking.status").value("CONFIRMED"))
                .andReturn().getResponse().getContentAsString();

        Instant heldUntil = Instant.parse(JsonPath.read(response, "$.booking.holdExpiresAt"));
        assertThat(heldUntil).isEqualTo(clock.instant().plus(Duration.ofMinutes(5)));
    }

    @Test
    void anExpiredHoldCantBePaidFor() throws Exception {
        String bookingId = hold(null, "A5");
        clock.advance(Duration.ofMinutes(9));

        pay(bookingId, UPI, "SUCCESS", UUID.randomUUID())
                .andExpect(status().isGone())
                .andExpect(jsonPath("$.code").value("HOLD_EXPIRED"));
    }

    @Test
    void aRetryReplaysTheAnswerAndAConfirmedBookingIsntPaidAgain() throws Exception {
        String bookingId = hold(null, "B2");
        UUID key = UUID.randomUUID();
        String first = pay(bookingId, UPI, "SUCCESS", key).andReturn().getResponse().getContentAsString();

        String retry = pay(bookingId, UPI, "SUCCESS", key).andReturn().getResponse().getContentAsString();
        assertThat(retry).isEqualTo(first);
        assertThat(jdbc.sql("SELECT count(*) FROM payment WHERE booking_id = ?")
                .param(UUID.fromString(bookingId)).query(Long.class).single()).isEqualTo(1L);

        pay(bookingId, UPI, "SUCCESS", UUID.randomUUID())         // a new attempt, not a retry
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.code").value("INVALID_STATE"));
    }

    private String hold(String couponCode, String... labels) throws Exception {
        String response = mvc.perform(asCustomer(post("/api/v1/bookings"), customer)
                        .header("Idempotency-Key", UUID.randomUUID())
                        .content("""
                                {"showId": %d, "seatIds": %s, "couponCode": %s}
                                """.formatted(show.id(), show.seats(labels).stream().sorted().toList(),
                                couponCode == null ? "null" : "\"" + couponCode + "\"")))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return JsonPath.read(response, "$.bookingId");
    }

    private ResultActions pay(String bookingId, String details, String simulate, UUID key) throws Exception {
        return mvc.perform(asCustomer(post("/api/v1/bookings/{id}/payments", bookingId), customer)
                .header("Idempotency-Key", key)
                .content("""
                        {"details": %s, "simulate": "%s"}
                        """.formatted(details, simulate)));
    }

    private String seatStatus(String label) {
        return jdbc.sql("SELECT status FROM show_seat WHERE show_id = ? AND layout_seat_id = ?")
                .params(show.id(), show.seatIdsByLabel().get(label)).query(String.class).single();
    }
}

package com.sumit.movieticketbookingsystem.booking.internal.service;

import com.sumit.movieticketbookingsystem.booking.internal.domain.Booking;
import com.sumit.movieticketbookingsystem.booking.internal.domain.BookingSeat;
import com.sumit.movieticketbookingsystem.booking.internal.domain.BookingStatus;
import com.sumit.movieticketbookingsystem.booking.internal.persistence.BookingRepository;
import com.sumit.movieticketbookingsystem.inventory.InventoryApi;
import com.sumit.movieticketbookingsystem.inventory.SeatsUnavailableException;
import com.sumit.movieticketbookingsystem.payment.InitiatePayment;
import com.sumit.movieticketbookingsystem.payment.PaymentApi;
import com.sumit.movieticketbookingsystem.payment.PaymentDetails;
import com.sumit.movieticketbookingsystem.payment.PaymentResult;
import com.sumit.movieticketbookingsystem.payment.RefundReason;
import com.sumit.movieticketbookingsystem.payment.RefundRequest;
import com.sumit.movieticketbookingsystem.payment.SimulatedOutcome;
import com.sumit.movieticketbookingsystem.pricing.CouponApi;
import com.sumit.movieticketbookingsystem.shared.BookingProperties;
import org.springframework.stereotype.Service;
import org.springframework.transaction.support.TransactionTemplate;

import java.time.Clock;
import java.time.Duration;
import java.time.Instant;
import java.util.UUID;
import java.util.stream.Collectors;

/**
 * Paying for a hold. Deliberately not one transaction: start the payment (tx1), call the gateway with no
 * transaction open so no locks are held while it works, then confirm or fail the booking (tx2). If the payment
 * succeeds after the seats were lost, the booking is closed and the payment refunded instead (tx3).
 */
@Service
public class CheckoutService {

    private final BookingRepository bookings;
    private final PaymentApi payments;
    private final InventoryApi inventory;
    private final CouponApi coupons;
    private final TransactionTemplate tx;
    private final Duration paymentWindow;
    private final Clock clock;

    CheckoutService(BookingRepository bookings, PaymentApi payments, InventoryApi inventory, CouponApi coupons,
            TransactionTemplate tx, BookingProperties properties, Clock clock) {
        this.bookings = bookings;
        this.payments = payments;
        this.inventory = inventory;
        this.coupons = coupons;
        this.tx = tx;
        this.paymentWindow = properties.paymentWindow();
        this.clock = clock;
    }

    public record Checkout(Booking booking, PaymentResult payment) {
    }

    // TransactionTemplate rather than @Transactional: the steps are private and called from here, where
    // Spring's proxy-based @Transactional wouldn't apply.
    public Checkout pay(UUID bookingId, UUID userId, PaymentDetails details, SimulatedOutcome outcome) {
        UUID paymentId = tx.execute(status -> startPayment(bookingId, userId, details));
        PaymentResult result = payments.execute(paymentId, details, outcome);
        Booking booking = switch (result.status()) {
            case SUCCESS -> completePayment(bookingId, true);
            case FAILED -> completePayment(bookingId, false);
            case PENDING -> bookings.findById(bookingId).orElseThrow();   // PAYMENT_PENDING until the event
        };
        return new Checkout(booking, result);
    }

    /**
     * What happens once the gateway has answered, straight away or later through an event. Safe to call twice
     * for the same payment, because a redelivered event finds the booking already settled.
     */
    public Booking completePayment(UUID bookingId, boolean paid) {
        if (!paid) {
            return tx.execute(status -> fail(bookingId));
        }
        try {
            Booking confirmed = tx.execute(status -> confirm(bookingId));
            if (confirmed != null) {
                return confirmed;
            }
        } catch (SeatsUnavailableException e) {
            // someone took the seats after this hold ran out; tx2 rolled back, so fall through to the refund
        }
        return tx.execute(status -> refundLatePayment(bookingId));
    }

    /** Invalid payment details roll this back too, leaving the booking HELD so the customer can try again. */
    private UUID startPayment(UUID bookingId, UUID userId, PaymentDetails details) {
        Booking booking = bookings.findOwn(bookingId, userId);
        Instant now = Instant.now(clock);
        if (booking.isHoldExpired(now)) {
            throw new HoldExpiredException(bookingId);
        }
        booking.startPayment(now, paymentWindow);
        return payments.initiate(new InitiatePayment(bookingId, userId, booking.getBookingRef(),
                booking.getTotals().total(), details));
    }

    /** @return the confirmed booking, or null if it can no longer be confirmed (so the payment must go back) */
    private Booking confirm(UUID bookingId) {
        Booking booking = bookings.findById(bookingId).orElseThrow();
        if (booking.getStatus() == BookingStatus.CONFIRMED) {
            return booking;                                        // the same payment reported twice
        }
        if (booking.getStatus() != BookingStatus.PAYMENT_PENDING) {
            return null;                                           // already expired while the payment was pending
        }
        Instant now = Instant.now(clock);
        inventory.confirm(booking.getShowId(),
                booking.getSeats().stream().map(BookingSeat::layoutSeatId).collect(Collectors.toSet()),
                bookingId, now);
        coupons.consume(bookingId);
        booking.confirm(now);
        return booking;
    }

    private Booking fail(UUID bookingId) {
        Booking booking = bookings.findById(bookingId).orElseThrow();
        if (booking.getStatus() != BookingStatus.PAYMENT_PENDING) {
            return booking;                                        // already expired or reported twice
        }
        booking.fail(Instant.now(clock));
        inventory.releaseHeld(booking.getShowId(), bookingId);
        coupons.release(bookingId);
        return booking;
    }

    /** The money came in but the seats are gone: close the booking and give every paisa back. */
    private Booking refundLatePayment(UUID bookingId) {
        Booking booking = bookings.findById(bookingId).orElseThrow();
        if (booking.getStatus().holdsSeats()) {
            booking.expire(Instant.now(clock));
            inventory.releaseHeld(booking.getShowId(), bookingId);
            coupons.release(bookingId);
        }
        payments.requestRefund(
                new RefundRequest(bookingId, null, booking.getTotals().total(), RefundReason.LATE_PAYMENT));
        return booking;
    }
}

package com.sumit.movieticketbookingsystem.booking;

import com.jayway.jsonpath.JsonPath;
import com.sumit.movieticketbookingsystem.TestDates;
import com.sumit.movieticketbookingsystem.TestcontainersConfiguration;
import com.sumit.movieticketbookingsystem.booking.BookingFixtures.BookableShow;
import com.sumit.movieticketbookingsystem.pricing.CouponFixtures;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;
import org.springframework.context.annotation.Import;
import org.springframework.jdbc.core.simple.JdbcClient;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.test.web.servlet.ResultActions;

import java.util.UUID;

import static com.sumit.movieticketbookingsystem.ApiRequests.asCustomer;
import static org.assertj.core.api.Assertions.assertThat;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.delete;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.put;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

/**
 * Coupons on real holds. Fixture prices: REGULAR ₹200, PREMIUM ₹300; Saturdays +20%.
 */
@SpringBootTest
@AutoConfigureMockMvc
@Import(TestcontainersConfiguration.class)
class BookingCouponIT {

    private static final String FIFTY_OFF = """
            "discountType": "FLAT", "discountValue": 5000, "minOrderPaise": 30000, "perUserLimit": 1""";

    @Autowired
    private MockMvc mvc;

    @Autowired
    private JdbcClient jdbc;

    private BookingFixtures shows;
    private CouponFixtures coupons;
    private UUID customer;

    @BeforeEach
    void setUp() {
        shows = new BookingFixtures(mvc, jdbc);
        coupons = new CouponFixtures(mvc);
        customer = UUID.randomUUID();
    }

    @Test
    void holdWithACouponMatchesTheWorkedExample() throws Exception {
        BookableShow saturday = shows.openShowOn(TestDates.saturday(2));
        String code = coupons.coupon(FIFTY_OFF);

        hold(saturday, code, "B1", "B2")
                .andExpect(status().isCreated())
                .andExpect(jsonPath("$.coupon").value(code))
                .andExpect(jsonPath("$.seats[0].amountPaise").value(41890))
                .andExpect(jsonPath("$.seats[1].amountPaise").value(41890))
                .andExpect(jsonPath("$.price.subtotalPaise").value(72000))
                .andExpect(jsonPath("$.price.discountPaise").value(5000))
                .andExpect(jsonPath("$.price.totalPaise").value(83780));
        assertThat(usedCount(code)).isEqualTo(1);
    }

    @Test
    void couponCanBeAddedSwappedAndRemovedOnAHold() throws Exception {
        BookableShow weekday = shows.openShowOn(TestDates.weekday(2));
        String fiftyOff = coupons.coupon(FIFTY_OFF);
        String tenPercent = coupons.coupon("""
                "discountType": "PERCENT", "discountValue": 10""");
        String bookingId = bookingId(hold(weekday, null, "A1", "A2")
                .andExpect(jsonPath("$.price.totalPaise").value(51920)));       // 2 x 25960

        changeCoupon(bookingId, fiftyOff)
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.price.discountPaise").value(5000))
                .andExpect(jsonPath("$.seats[0].amountPaise").value(25960 - 2500 - 450));   // less discount and its GST
        changeCoupon(bookingId, tenPercent)
                .andExpect(jsonPath("$.coupon").value(tenPercent))
                .andExpect(jsonPath("$.price.discountPaise").value(4000));
        assertThat(usedCount(fiftyOff)).isZero();                                          // given back on the swap
        assertThat(usedCount(tenPercent)).isEqualTo(1);

        mvc.perform(asCustomer(delete("/api/v1/bookings/{id}/coupon", bookingId), customer))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.coupon").doesNotExist())
                .andExpect(jsonPath("$.price.totalPaise").value(51920));
        assertThat(usedCount(tenPercent)).isZero();
    }

    @Test
    void releasingAHoldGivesTheCouponBack() throws Exception {
        BookableShow weekday = shows.openShowOn(TestDates.weekday(2));
        String code = coupons.coupon(FIFTY_OFF);
        String bookingId = bookingId(hold(weekday, code, "B3").andExpect(status().isCreated()));

        mvc.perform(asCustomer(post("/api/v1/bookings/{id}/release", bookingId), customer)).andExpect(status().isOk());

        assertThat(usedCount(code)).isZero();
        hold(weekday, code, "B4").andExpect(status().isCreated());       // so the same customer may use it again
    }

    @Test
    void perUserLimitHoldsAcrossShows() throws Exception {
        String code = coupons.coupon(FIFTY_OFF);
        hold(shows.openShow(), code, "B1").andExpect(status().isCreated());

        hold(shows.openShow(), code, "B1")
                .andExpect(status().isUnprocessableContent())
                .andExpect(jsonPath("$.code").value("COUPON_INVALID"))
                .andExpect(jsonPath("$.detail").value("You've already used this coupon"));
        assertThat(usedCount(code)).isEqualTo(1);
    }

    @Test
    void anInvalidCouponFailsTheWholeHold() throws Exception {
        BookableShow weekday = shows.openShowOn(TestDates.weekday(2));
        String bigOrdersOnly = coupons.coupon("""
                "discountType": "FLAT", "discountValue": 5000, "minOrderPaise": 100000""");

        hold(weekday, bigOrdersOnly, "A3")
                .andExpect(status().isUnprocessableContent())
                .andExpect(jsonPath("$.code").value("COUPON_INVALID"));
        assertThat(jdbc.sql("SELECT status FROM show_seat WHERE show_id = ? AND layout_seat_id = ?")
                .params(weekday.id(), weekday.seatIdsByLabel().get("A3")).query(String.class).single())
                .isEqualTo("AVAILABLE");                                     // the seat claim was rolled back too
    }

    private ResultActions hold(BookableShow show, String couponCode, String... labels) throws Exception {
        return mvc.perform(asCustomer(post("/api/v1/bookings"), customer)
                .header("Idempotency-Key", UUID.randomUUID())
                .content("""
                        {"showId": %d, "seatIds": %s, "couponCode": %s}
                        """.formatted(show.id(), show.seats(labels).stream().sorted().toList(),
                        couponCode == null ? "null" : "\"" + couponCode.toLowerCase() + "\"")));
    }

    private ResultActions changeCoupon(String bookingId, String code) throws Exception {
        return mvc.perform(asCustomer(put("/api/v1/bookings/{id}/coupon", bookingId), customer)
                .content("{\"code\": \"" + code + "\"}"));
    }

    private static String bookingId(ResultActions hold) throws Exception {
        return JsonPath.read(hold.andReturn().getResponse().getContentAsString(), "$.bookingId");
    }

    private int usedCount(String code) {
        return jdbc.sql("SELECT used_count FROM coupon WHERE code = ?").param(code).query(Integer.class).single();
    }
}

