import java.time.Clock;
import java.time.Instant;
import java.util.EnumSet;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.Set;
import java.util.UUID;
import java.util.function.Function;
import java.util.stream.Collectors;

/**
 * Holding seats, letting them go, changing the coupon on a hold, and looking up a customer's booking. A hold is one
 * transaction across inventory, pricing and booking, so it either happens completely or not at all.
 */
@Service
public class HoldService {

    private static final Set<BookingStatus> LIVE = EnumSet.of(BookingStatus.HELD, BookingStatus.PAYMENT_PENDING);

    private final BookingRepository bookings;
    private final ShowApi shows;
    private final InventoryApi inventory;
    private final PricingApi pricing;
    private final CouponApi coupons;
    private final BookingRefGenerator refs;
    private final BookingProperties properties;
    private final Clock clock;

    HoldService(BookingRepository bookings, ShowApi shows, InventoryApi inventory, PricingApi pricing,
            CouponApi coupons, BookingRefGenerator refs, BookingProperties properties, Clock clock) {
        this.bookings = bookings;
        this.shows = shows;
        this.inventory = inventory;
        this.pricing = pricing;
        this.coupons = coupons;
        this.refs = refs;
        this.properties = properties;
        this.clock = clock;
    }

    /** @param couponCode optional */
    public record CreateHold(UUID userId, long showId, Set<Long> seatIds, String couponCode) {
    }

    @Transactional
    public Booking createHold(CreateHold command) {
        Instant now = Instant.now(clock);
        if (command.seatIds().isEmpty() || command.seatIds().size() > properties.maxSeatsPerBooking()) {
            throw new ValidationException("Pick between 1 and " + properties.maxSeatsPerBooking() + " seats");
        }
        ShowDetails show = shows.show(command.showId());
        if (!show.isBookable(now, properties.bookingCutoff())) {
            throw new ShowNotBookableException(show.showId());
        }
        replaceLapsedHold(command.userId(), show.showId(), now);

        UUID bookingId = UUID.randomUUID();
        List<HeldSeat> held = inventory.hold(show.showId(), command.seatIds(), bookingId,
                now.plus(properties.holdDuration()), now);
        List<SeatToBook> seats = held.stream()
                .map(seat -> new SeatToBook(seat.layoutSeatId(), seat.label(), seat.categoryId()))
                .toList();
        PriceQuote quote = quote(show, command.userId(), seats, command.couponCode());
        reserveCoupon(quote, command.userId(), bookingId);

        // ponytail: a booking_ref clash (1 in ~10^9 per hold) fails this hold with a 500; retry with a fresh
        // ref here if that ever shows up in the logs
        Booking booking = Booking.hold(bookingId, refs.next(), command.userId(), show.showId(), show.startTime(),
                now.plus(properties.holdDuration()), bookingSeats(seats, quote), totals(quote), quote.coupon(), now);
        try {
            return bookings.saveAndFlush(booking);
        } catch (DataIntegrityViolationException e) {
            if (ConstraintViolations.isViolationOf(e, "booking_one_active_hold")) {
                throw new ActiveHoldExistsException(null);   // a parallel request from the same customer won
            }
            throw e;
        }
    }

    /**
     * Swaps the coupon on a live hold, or removes it when {@code couponCode} is null. The seats and the hold's
     * expiry stay as they are; only the price changes.
     */
    @Transactional
    public Booking changeCoupon(UUID bookingId, UUID userId, String couponCode) {
        Booking booking = bookings.findOwn(bookingId, userId);
        if (booking.isHoldExpired(Instant.now(clock))) {
            throw new HoldExpiredException(bookingId);
        }
        coupons.release(bookingId);
        List<SeatToBook> seats = booking.getSeats().stream()
                .map(seat -> new SeatToBook(seat.layoutSeatId(), seat.seatLabel(), seat.categoryId()))
                .toList();
        PriceQuote quote = quote(shows.show(booking.getShowId()), userId, seats, couponCode);
        reserveCoupon(quote, userId, bookingId);
        booking.reprice(bookingSeats(seats, quote), totals(quote), quote.coupon());
        return booking;
    }

    @Transactional
    public Booking release(UUID bookingId, UUID userId) {
        Booking booking = bookings.findOwn(bookingId, userId);
        booking.release(Instant.now(clock));
        inventory.releaseHeld(booking.getShowId(), booking.getId());
        coupons.release(booking.getId());
        return booking;
    }

    @Transactional(readOnly = true)
    public Booking booking(UUID bookingId, UUID userId) {
        return bookings.findOwn(bookingId, userId);
    }

    /**
     * A customer's old hold on the same show that has already run out is closed so they can hold again.
     * The flush matters: Hibernate runs inserts before updates, so without it the new booking would hit
     * booking_one_active_hold while the old one still looks live.
     */
    private void replaceLapsedHold(UUID userId, long showId, Instant now) {
        Optional<Booking> live = bookings.findByUserIdAndShowIdAndStatusIn(userId, showId, LIVE);
        if (live.isEmpty()) {
            return;
        }
        Booking existing = live.get();
        if (!existing.isHoldExpired(now)) {
            throw new ActiveHoldExistsException(existing.getId());
        }
        existing.expire(now);
        inventory.releaseHeld(showId, existing.getId());
        coupons.release(existing.getId());
        bookings.saveAndFlush(existing);
    }

    private PriceQuote quote(ShowDetails show, UUID userId, List<SeatToBook> seats, String couponCode) {
        ShowPricing showPricing = new ShowPricing(show.showId(), show.movieId(), show.cityId(), show.theaterId(),
                show.showDate());
        return pricing.quote(new PricingRequest(showPricing, userId,
                seats.stream().map(seat -> new SeatToPrice(seat.layoutSeatId(), seat.categoryId())).toList(),
                couponCode));
    }

    private void reserveCoupon(PriceQuote quote, UUID userId, UUID bookingId) {
        if (quote.coupon() != null) {
            coupons.reserve(quote.coupon(), userId, bookingId, quote.discountPaise());
        }
    }

    private static List<BookingSeat> bookingSeats(List<SeatToBook> seats, PriceQuote quote) {
        Map<Long, SeatPriceLine> lines = quote.lines().stream()
                .collect(Collectors.toMap(SeatPriceLine::layoutSeatId, Function.identity()));
        return seats.stream()
                .map(seat -> {
                    SeatPriceLine line = lines.get(seat.layoutSeatId());
                    return new BookingSeat(seat.layoutSeatId(), seat.label(), seat.categoryId(), line.basePaise(),
                            line.discountPaise(), line.feePaise() + line.feeTaxPaise(), line.amountPaise());
                })
                .toList();
    }

    private static PriceTotals totals(PriceQuote quote) {
        return new PriceTotals(quote.subtotalPaise(), quote.discountPaise(), quote.feePaise(), quote.taxPaise(),
                quote.totalPaise());
    }

    private record SeatToBook(long layoutSeatId, String label, long categoryId) {
    }
}

package com.sumit.movieticketbookingsystem.booking.internal.domain;

import com.sumit.movieticketbookingsystem.shared.error.IllegalTransitionException;
import org.junit.jupiter.api.Test;

import java.time.Duration;
import java.time.Instant;
import java.util.List;
import java.util.UUID;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

class BookingTest {

    private static final Instant NOW = Instant.parse("2026-10-03T10:00:00Z");
    private static final Instant EXPIRES = NOW.plus(Duration.ofMinutes(8));

    // two regular seats at ₹200: fee ₹20 + 18% GST on each, see the pricing worked example
    private static final List<BookingSeat> SEATS = List.of(
            new BookingSeat(12, "F8", 1, 20000, 0, 2360, 25960),
            new BookingSeat(11, "F7", 1, 20000, 0, 2360, 25960));
    private static final PriceTotals TOTALS = new PriceTotals(40000, 0, 4000, 7920, 51920);

    @Test
    void holdStartsHeldWithFrozenPrices() {
        Booking booking = hold();

        assertThat(booking.getStatus()).isEqualTo(BookingStatus.HELD);
        assertThat(booking.getStatus().holdsSeats()).isTrue();
        assertThat(booking.getTotals()).isEqualTo(TOTALS);
        assertThat(booking.getSeats()).extracting(BookingSeat::seatLabel).containsExactly("F7", "F8");
    }

    @Test
    void seatAmountsMustAddUpToTheTotal() {
        PriceTotals wrong = new PriceTotals(40000, 0, 4000, 8000, 52000);

        assertThatThrownBy(() -> Booking.hold(UUID.randomUUID(), "BK000001", UUID.randomUUID(), 1,
                NOW.plusSeconds(86400), EXPIRES, SEATS, wrong, null, NOW))
                .isInstanceOf(IllegalArgumentException.class);
        assertThatThrownBy(() -> new PriceTotals(100, 0, 10, 10, 999)).isInstanceOf(IllegalArgumentException.class);
    }

    @Test
    void releaseAndExpireCloseTheBooking() {
        Booking released = hold();
        released.release(NOW.plusSeconds(60));
        assertThat(released.getStatus()).isEqualTo(BookingStatus.RELEASED);
        assertThat(released.getClosedAt()).isEqualTo(NOW.plusSeconds(60));
        assertThat(released.getStatus().holdsSeats()).isFalse();

        Booking expired = hold();
        expired.expire(EXPIRES);
        assertThat(expired.getStatus()).isEqualTo(BookingStatus.EXPIRED);
    }

    @Test
    void closedBookingsCantChangeAgain() {
        Booking booking = hold();
        booking.release(NOW);

        assertThatThrownBy(() -> booking.expire(NOW))
                .isInstanceOf(IllegalTransitionException.class)
                .hasMessage("Booking cannot move from RELEASED to EXPIRED");
    }

    @Test
    void startingPaymentKeepsTheSeatsForThePaymentWindowButNeverShortensTheHold() {
        Booking early = hold();                                   // hold runs until NOW + 8 min
        early.startPayment(NOW, Duration.ofMinutes(5));
        assertThat(early.getStatus()).isEqualTo(BookingStatus.PAYMENT_PENDING);
        assertThat(early.getHoldExpiresAt()).isEqualTo(EXPIRES);

        Booking late = hold();
        late.startPayment(NOW.plus(Duration.ofMinutes(7)), Duration.ofMinutes(5));
        assertThat(late.getHoldExpiresAt()).isEqualTo(NOW.plus(Duration.ofMinutes(12)));
    }

    @Test
    void paymentEndsConfirmedOrFailed() {
        Booking paid = hold();
        paid.startPayment(NOW, Duration.ofMinutes(5));
        paid.confirm(NOW.plusSeconds(30));
        assertThat(paid.getStatus()).isEqualTo(BookingStatus.CONFIRMED);
        assertThat(paid.getConfirmedAt()).isEqualTo(NOW.plusSeconds(30));

        Booking declined = hold();
        declined.startPayment(NOW, Duration.ofMinutes(5));
        declined.fail(NOW.plusSeconds(30));
        assertThat(declined.getStatus()).isEqualTo(BookingStatus.FAILED);
        assertThat(declined.getClosedAt()).isEqualTo(NOW.plusSeconds(30));

        assertThatThrownBy(() -> hold().confirm(NOW)).isInstanceOf(IllegalTransitionException.class);   // not paid
    }

    @Test
    void holdExpiresExactlyAtItsExpiryTime() {
        Booking booking = hold();

        assertThat(booking.isHoldExpired(EXPIRES.minusSeconds(1))).isFalse();
        assertThat(booking.isHoldExpired(EXPIRES)).isTrue();
        booking.release(NOW);
        assertThat(booking.isHoldExpired(EXPIRES)).isFalse();     // only a live hold can expire
    }

    private static Booking hold() {
        return Booking.hold(UUID.randomUUID(), "BK000001", UUID.randomUUID(), 1, NOW.plusSeconds(86400), EXPIRES,
                SEATS, TOTALS, null, NOW);
    }
}

