package com.sumit.movieticketbookingsystem.pricing.internal.coupon;

import com.sumit.movieticketbookingsystem.pricing.internal.coupon.Coupon.Terms;
import com.sumit.movieticketbookingsystem.shared.error.ValidationException;
import jakarta.validation.Valid;
import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Positive;
import jakarta.validation.constraints.PositiveOrZero;
import jakarta.validation.constraints.Size;
import org.springframework.http.HttpStatus;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

import java.time.Instant;
import java.time.OffsetDateTime;
import java.util.Comparator;
import java.util.List;
import java.util.Set;

@RestController
@RequestMapping("/api/v1/admin/coupons")
class CouponAdminController {

    private final CouponAdminService couponService;

    CouponAdminController(CouponAdminService couponService) {
        this.couponService = couponService;
    }

    @GetMapping
    List<CouponResponse> coupons() {
        return couponService.coupons().stream().map(CouponResponse::from).toList();
    }

    @PostMapping
    @ResponseStatus(HttpStatus.CREATED)
    CouponResponse create(@Valid @RequestBody CouponRequest request) {
        if (request.code() == null || request.code().isBlank()) {
            throw new ValidationException("A new coupon needs a code");
        }
        return CouponResponse.from(couponService.create(request.code(), request.toTerms()));
    }

    @PutMapping("/{id}")
    CouponResponse update(@PathVariable long id, @Valid @RequestBody CouponRequest request) {
        return CouponResponse.from(couponService.update(id, request.code(), request.toTerms()));
    }

    @PostMapping("/{id}/deactivate")
    @ResponseStatus(HttpStatus.NO_CONTENT)
    void deactivate(@PathVariable long id) {
        couponService.deactivate(id);
    }

    /**
     * Amounts in paise. {@code code} is required when creating and can't change afterwards (leave it out when
     * updating). {@code maxUses} empty = unlimited; {@code scopes} empty = valid everywhere.
     */
    record CouponRequest(
            @Size(max = 30) String code,
            @NotNull DiscountType discountType,
            @NotNull @Positive Long discountValue,
            @Positive Long maxDiscountPaise,
            @PositiveOrZero Long minOrderPaise,
            @NotNull OffsetDateTime validFrom,
            @NotNull OffsetDateTime validTo,
            @Positive Integer maxUses,
            @Min(1) Integer perUserLimit,
            Set<@NotNull CouponScope> scopes) {

        Terms toTerms() {
            return new Terms(discountType, discountValue, maxDiscountPaise, minOrderPaise == null ? 0 : minOrderPaise,
                    validFrom.toInstant(), validTo.toInstant(), maxUses, perUserLimit == null ? 1 : perUserLimit,
                    scopes == null ? Set.of() : scopes);
        }
    }

    record CouponResponse(long id, String code, DiscountType discountType, long discountValue, Long maxDiscountPaise,
                          long minOrderPaise, Instant validFrom, Instant validTo, Integer maxUses, int usedCount,
                          int perUserLimit, boolean active, List<CouponScope> scopes) {

        static CouponResponse from(Coupon coupon) {
            return new CouponResponse(coupon.getId(), coupon.getCode(), coupon.getDiscountType(),
                    coupon.getDiscountValue(), coupon.getMaxDiscountPaise(), coupon.getMinOrderPaise(),
                    coupon.getValidFrom(), coupon.getValidTo(), coupon.getMaxUses(), coupon.getUsedCount(),
                    coupon.getPerUserLimit(), coupon.isActive(),
                    coupon.getScopes().stream()
                            .sorted(Comparator.comparing(CouponScope::scopeType).thenComparing(CouponScope::scopeId))
                            .toList());
        }
    }
}
package com.sumit.movieticketbookingsystem.pricing.internal.coupon;

import com.sumit.movieticketbookingsystem.catalog.CatalogApi;
import com.sumit.movieticketbookingsystem.catalog.SeatCategoryInfo;
import com.sumit.movieticketbookingsystem.pricing.internal.coupon.Coupon.Terms;
import com.sumit.movieticketbookingsystem.shared.error.AlreadyExistsException;
import com.sumit.movieticketbookingsystem.shared.error.NotFoundException;
import com.sumit.movieticketbookingsystem.shared.error.ValidationException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.List;
import java.util.Locale;
import java.util.Set;
import java.util.regex.Pattern;

@Service
class CouponAdminService {

    private static final Pattern CODE = Pattern.compile("[A-Z0-9]{3,30}");

    private final CouponRepository coupons;
    private final CatalogApi catalog;

    CouponAdminService(CouponRepository coupons, CatalogApi catalog) {
        this.coupons = coupons;
        this.catalog = catalog;
    }

    @Transactional(readOnly = true)
    public List<Coupon> coupons() {
        return coupons.findAllByOrderByIdDesc();
    }

    @Transactional
    public Coupon create(String code, Terms terms) {
        String normalized = normalize(code);
        if (!CODE.matcher(normalized).matches()) {
            throw new ValidationException("Coupon codes are 3-30 letters and digits");
        }
        if (coupons.existsByCode(normalized)) {
            throw new AlreadyExistsException("Coupon", normalized);
        }
        validate(terms, 0);
        return coupons.save(new Coupon(normalized, terms));
    }

    /** @param code null, or the coupon's current code; codes never change */
    @Transactional
    public Coupon update(long id, String code, Terms terms) {
        Coupon coupon = find(id);
        if (code != null && !normalize(code).equals(coupon.getCode())) {
            throw new ValidationException("A coupon's code can't be changed");
        }
        validate(terms, coupon.getUsedCount());
        coupon.update(terms);
        return coupon;
    }

    @Transactional
    public void deactivate(long id) {
        find(id).deactivate();
    }

    private void validate(Terms terms, int usedSoFar) {
        switch (terms.discountType()) {
            case PERCENT -> {
                if (terms.discountValue() > 100) {
                    throw new ValidationException("A percentage discount can be at most 100%");
                }
            }
            case FLAT -> {
                if (terms.maxDiscountPaise() != null) {
                    throw new ValidationException("Only percentage coupons have a maximum discount");
                }
            }
        }
        if (!terms.validTo().isAfter(terms.validFrom())) {
            throw new ValidationException("validTo must be after validFrom");
        }
        if (terms.maxUses() != null && terms.maxUses() < usedSoFar) {
            throw new ValidationException("maxUses can't go below the " + usedSoFar + " uses already made");
        }
        terms.scopes().forEach(this::requireTarget);
    }

    private void requireTarget(CouponScope scope) {
        long id = scope.scopeId();
        switch (scope.scopeType()) {
            case CITY -> catalog.city(id);
            case MOVIE -> catalog.movie(id);
            case THEATER -> {
                if (catalog.theaters(Set.of(id)).isEmpty()) {
                    throw new NotFoundException("Theater", id);
                }
            }
            case CATEGORY -> {
                if (catalog.seatCategories().stream().map(SeatCategoryInfo::categoryId).noneMatch(c -> c == id)) {
                    throw new NotFoundException("Seat category", id);
                }
            }
        }
    }

    private static String normalize(String code) {
        return code.strip().toUpperCase(Locale.ROOT);
    }

    private Coupon find(long id) {
        return coupons.findById(id).orElseThrow(() -> new NotFoundException("Coupon", id));
    }
}
package com.sumit.movieticketbookingsystem.pricing.internal.coupon;

import com.sumit.movieticketbookingsystem.shared.persistence.AuditedEntity;
import jakarta.persistence.CollectionTable;
import jakarta.persistence.Column;
import jakarta.persistence.ElementCollection;
import jakarta.persistence.Entity;
import jakarta.persistence.EnumType;
import jakarta.persistence.Enumerated;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.JoinColumn;

import java.time.Instant;
import java.util.HashSet;
import java.util.Set;

@Entity
public class Coupon extends AuditedEntity {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    private String code;

    @Enumerated(EnumType.STRING)
    private DiscountType discountType;

    private long discountValue;

    private Long maxDiscountPaise;

    private long minOrderPaise;

    private Instant validFrom;

    private Instant validTo;

    private Integer maxUses;

    // Read-only here: only the redemption SQL changes it, atomically. If JPA wrote it back, an admin edit
    // racing a customer's redemption would lose that use.
    @Column(insertable = false, updatable = false)
    private int usedCount;

    private int perUserLimit;

    private boolean active = true;

    @ElementCollection
    @CollectionTable(name = "coupon_scope", joinColumns = @JoinColumn(name = "coupon_id"))
    private Set<CouponScope> scopes = new HashSet<>();

    protected Coupon() {
    }

    public Coupon(String code, Terms terms) {
        this.code = code;
        update(terms);
    }

    public void update(Terms terms) {
        this.discountType = terms.discountType();
        this.discountValue = terms.discountValue();
        this.maxDiscountPaise = terms.maxDiscountPaise();
        this.minOrderPaise = terms.minOrderPaise();
        this.validFrom = terms.validFrom();
        this.validTo = terms.validTo();
        this.maxUses = terms.maxUses();
        this.perUserLimit = terms.perUserLimit();
        this.scopes.clear();
        this.scopes.addAll(terms.scopes());
    }

    public void deactivate() {
        this.active = false;
    }

