package com.sumit.movieticketbookingsystem.booking.internal.domain;

import com.sumit.movieticketbookingsystem.shared.error.IllegalTransitionException;

import java.util.EnumSet;
import java.util.Set;

/**
 * <pre>
 * HELD ──► PAYMENT_PENDING ──► CONFIRMED ──► CANCELLED
 *   │            ├──► FAILED
 *   │            └──► EXPIRED   (seats lost while paying; refunded)
 *   ├──► RELEASED               (customer let go, or show cancelled)
 *   └──► EXPIRED                (hold time ran out)
 * </pre>
 * Cancelling only some seats keeps a booking CONFIRMED. Refund progress lives on the refund, not here.
 */
public enum BookingStatus {

    HELD {
        @Override
        Set<BookingStatus> next() {
            return EnumSet.of(PAYMENT_PENDING, RELEASED, EXPIRED);
        }
    },
    PAYMENT_PENDING {
        @Override
        Set<BookingStatus> next() {
            return EnumSet.of(CONFIRMED, FAILED, EXPIRED);
        }
    },
    CONFIRMED {
        @Override
        Set<BookingStatus> next() {
            return EnumSet.of(CANCELLED);
        }
    },
    CANCELLED,
    RELEASED,
    EXPIRED,
    FAILED;

    Set<BookingStatus> next() {
        return EnumSet.noneOf(BookingStatus.class);
    }

    /** HELD and PAYMENT_PENDING bookings own their seats in inventory. */
    public boolean holdsSeats() {
        return this == HELD || this == PAYMENT_PENDING;
    }

    BookingStatus transitionTo(BookingStatus target) {
        if (!next().contains(target)) {
            throw new IllegalTransitionException("Booking", this, target);
        }
        return target;
    }
}
package com.sumit.movieticketbookingsystem.booking.internal.domain;

import jakarta.persistence.Embeddable;

/**
 * One seat of a booking with the price it was held at. Amounts are in paise.
 *
 * @param feePaise    convenience fee plus the GST on it
 * @param amountPaise everything this seat costs: base − discount + fee + ticket GST
 */
@Embeddable
public record BookingSeat(long layoutSeatId, String seatLabel, long categoryId, long basePaise,
                          long discountPaise, long feePaise, long amountPaise) {

    public BookingSeat {
        if (amountPaise < feePaise) {
            throw new IllegalArgumentException("Seat " + seatLabel + " costs less than its fee");
        }
    }
}
package com.sumit.movieticketbookingsystem.inventory;

import com.sumit.movieticketbookingsystem.catalog.LayoutView;

import java.time.Instant;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.UUID;

/**
 * The seats of each show. Every change is a conditional update on the seat rows, so it's safe under concurrency.
 */
public interface InventoryApi {

    /** Creates the show's seat rows from its layout; seats blocked in the layout start out blocked. */
    void initializeSeats(long showId, LayoutView layout);

    /** Blocks seats that are available and returns the ids that weren't, e.g. already blocked or unknown. */
    Set<Long> block(long showId, Set<Long> seatIds);

    /** Unblocks seats that are blocked and returns the ids that weren't. */
    Set<Long> unblock(long showId, Set<Long> seatIds);

    /**
     * Claims every requested seat for the booking, or none of them. Seats are free when they're available or
     * their hold ran out before {@code now}. Rows are locked in seat order and never waited on, so two holds
     * can't deadlock and a customer racing for the same seat gets an answer straight away.
     *
     * @throws SeatsUnavailableException if any seat is taken, locked by another hold, or not part of the show
     */
    List<HeldSeat> hold(long showId, Set<Long> seatIds, UUID bookingId, Instant expiresAt, Instant now);

    /**
     * Books the seats for good once they're paid for. Each seat must still be held by this booking, or be free
     * again (its hold ran out and nobody took it). Waits for row locks rather than failing: a customer who has
     * paid shouldn't lose out to a brief lock.
     *
     * @throws SeatsUnavailableException if another booking has any of the seats now; nothing is booked then
     */
    void confirm(long showId, Set<Long> seatIds, UUID bookingId, Instant now);

    /** Frees the seats the booking still holds (release, expiry, failed payment); returns how many. */
    int releaseHeld(long showId, UUID bookingId);

    /**
     * Current status of every seat of the show, by layout seat id. Always read from the database;
     * a hold that ran out before {@code now} reads as AVAILABLE.
     */
    Map<Long, SeatStatus> seatStatuses(long showId, Instant now);
}
package com.sumit.movieticketbookingsystem.shared.error;

import org.springframework.http.HttpStatus;

/**
 * Stable error codes returned to clients in the {@code code} field of every error response.
 * Clients branch on these, so never rename one once it has shipped.
 */
public enum ErrorCode {

    VALIDATION_FAILED(HttpStatus.BAD_REQUEST, "Validation failed"),
    UNAUTHENTICATED(HttpStatus.UNAUTHORIZED, "Unauthenticated"),
    FORBIDDEN(HttpStatus.FORBIDDEN, "Forbidden"),
    NOT_FOUND(HttpStatus.NOT_FOUND, "Not found"),
    ALREADY_EXISTS(HttpStatus.CONFLICT, "Already exists"),
    INVALID_STATE(HttpStatus.CONFLICT, "Invalid state"),
    SHOW_OVERLAP(HttpStatus.CONFLICT, "Show overlaps another show"),
    SEATS_UNAVAILABLE(HttpStatus.CONFLICT, "Seats unavailable"),
    ACTIVE_HOLD_EXISTS(HttpStatus.CONFLICT, "Active hold exists"),
    IDEMPOTENCY_KEY_REUSED(HttpStatus.CONFLICT, "Idempotency key reused"),
    IDEMPOTENCY_IN_PROGRESS(HttpStatus.CONFLICT, "Request still in progress"),
    COUPON_INVALID(HttpStatus.UNPROCESSABLE_CONTENT, "Coupon can't be used"),
    SHOW_NOT_BOOKABLE(HttpStatus.UNPROCESSABLE_CONTENT, "Show not bookable"),
    HOLD_EXPIRED(HttpStatus.GONE, "Hold expired"),
    INTERNAL_ERROR(HttpStatus.INTERNAL_SERVER_ERROR, "Internal error");

    private final HttpStatus status;
    private final String title;

    ErrorCode(HttpStatus status, String title) {
        this.status = status;
        this.title = title;
    }

    public HttpStatus status() {
        return status;
    }

    public String title() {
        return title;
    }
}
package com.sumit.movieticketbookingsystem.pricing;

import java.util.UUID;

/**
 * Using coupons up. Both calls join the caller's transaction, so a failed hold also undoes its coupon.
 */
public interface CouponApi {

    /**
     * Takes one use of the coupon for the booking, within the coupon's total and per-customer limits.
     *
     * @throws CouponInvalidException if either limit has been reached (or the coupon was just deactivated)
     */
    void reserve(String code, UUID userId, UUID bookingId, long discountPaise);

    /** Marks the booking's reserved coupon as used for good, once the booking is paid. No-op without a coupon. */
    void consume(UUID bookingId);

    /** Gives the booking's coupon use back, if it has one. */
    void release(UUID bookingId);
}
    protected Booking() {
    }

    /** @param couponCode the coupon the price includes, or null */
    public static Booking hold(UUID id, String bookingRef, UUID userId, long showId, Instant showStartTime,
            Instant holdExpiresAt, List<BookingSeat> seats, PriceTotals totals, String couponCode, Instant now) {
        if (seats.isEmpty()) {
            throw new IllegalArgumentException("A booking needs at least one seat");
        }
        requireSeatsAddUp(seats, totals);

        Booking booking = new Booking();
        booking.id = id;
        booking.bookingRef = bookingRef;
        booking.userId = userId;
        booking.showId = showId;
        booking.showStartTime = showStartTime;
        booking.status = BookingStatus.HELD;
        booking.holdExpiresAt = holdExpiresAt;
        booking.seats.addAll(seats);
        booking.seatCount = seats.size();
        booking.setPrice(totals, couponCode);
        booking.createdAt = now;
        return booking;
    }

    /**
     * Replaces the frozen price after the customer changes the coupon on a live hold. Same seats, new amounts.
     */
    public void reprice(List<BookingSeat> newSeats, PriceTotals totals, String newCouponCode) {
        if (status != BookingStatus.HELD) {
            throw new InvalidStateException("Only a held booking can change its coupon; this one is " + status);
        }
        Set<Long> current = seats.stream().map(BookingSeat::layoutSeatId).collect(Collectors.toSet());
        Set<Long> replacement = newSeats.stream().map(BookingSeat::layoutSeatId).collect(Collectors.toSet());
        if (!current.equals(replacement)) {
            throw new IllegalArgumentException("A new price must cover exactly the booking's seats");
        }
        requireSeatsAddUp(newSeats, totals);
        seats.clear();
        seats.addAll(newSeats);
        setPrice(totals, newCouponCode);
    }

    /**
     * The customer starts paying. The seats stay reserved for at least {@code paymentWindow} from now, so a
     * payment started just before the hold runs out still has time to finish; an existing longer hold isn't cut.
     */
    public void startPayment(Instant now, Duration paymentWindow) {
        status = status.transitionTo(BookingStatus.PAYMENT_PENDING);
        Instant paymentDeadline = now.plus(paymentWindow);
        if (paymentDeadline.isAfter(holdExpiresAt)) {
            holdExpiresAt = paymentDeadline;
        }
    }

    /** @param refundPolicy the terms this booking is sold under; kept even if the policy is edited later */
    public void confirm(RefundPolicySnapshot refundPolicy, Instant now) {
        status = status.transitionTo(BookingStatus.CONFIRMED);
        refundPolicySnapshot = refundPolicy;
        confirmedAt = now;
    }

    /** The payment was declined; the customer starts again with a new hold. */
    public void fail(Instant now) {
        close(BookingStatus.FAILED, now);
    }

    /** The customer lets the hold go before it runs out. */
    public void release(Instant now) {
        close(BookingStatus.RELEASED, now);
    }

    /** The hold ran out; the seats may already belong to someone else. */
    public void expire(Instant now) {
        close(BookingStatus.EXPIRED, now);
    }

    public boolean isHoldExpired(Instant now) {
        return status == BookingStatus.HELD && !now.isBefore(holdExpiresAt);
    }

