// Talks to the booking API. Every call says who is making it, the way the gateway would in production.

const BASE_URL_KEY = 'moviebooking.baseUrl';
const DEFAULT_BASE_URL = 'http://localhost:8080';

export function baseUrl() {
    return localStorage.getItem(BASE_URL_KEY) || DEFAULT_BASE_URL;
}

export function setBaseUrl(url) {
    localStorage.setItem(BASE_URL_KEY, url.replace(/\/+$/, ''));
}

/** A problem+json error from the API, or a network failure (status 0). */
export class ApiError extends Error {
    constructor(status, problem) {
        super(problem.detail || problem.title || `HTTP ${status}`);
        this.status = status;
        this.code = problem.code;
        this.problem = problem;
    }
}

/**
 * @param identity {id, role, name?, email?, phone?}
 * @param options.body sent as JSON
 * @param options.key an Idempotency-Key; pass the same one when retrying the same action
 */
export async function api(path, identity, {method = 'GET', body, key} = {}) {
    const headers = {'X-User-Id': identity.id, 'X-User-Role': identity.role};
    for (const [header, value] of [['X-User-Name', identity.name], ['X-User-Email', identity.email],
                                   ['X-User-Phone', identity.phone]]) {
        if (value) {
            headers[header] = value;
        }
    }
    if (body !== undefined) {
        headers['Content-Type'] = 'application/json';
    }
    if (key) {
        headers['Idempotency-Key'] = key;
    }

    let response;
    try {
        response = await fetch(baseUrl() + path, {method, headers, body: body === undefined ? undefined : JSON.stringify(body)});
    } catch (e) {
        throw new ApiError(0, {detail: `Can't reach the API at ${baseUrl()}. Is the app running?`});
    }
    if (response.status === 204) {
        return null;
    }
    const text = await response.text();
    const json = text ? JSON.parse(text) : null;
    if (!response.ok) {
        throw new ApiError(response.status, json || {});
    }
    return json;
}

export function newKey() {
    return crypto.randomUUID();
}

/** An identity kept in this browser, created on first use. */
export function storedIdentity(storageKey, defaults) {
    const saved = localStorage.getItem(storageKey);
    if (saved) {
        return JSON.parse(saved);
    }
    const identity = {id: crypto.randomUUID(), ...defaults};
    localStorage.setItem(storageKey, JSON.stringify(identity));
    return identity;
}

export function saveIdentity(storageKey, identity) {
    localStorage.setItem(storageKey, JSON.stringify(identity));
}

// ---- formatting ----

const ZONE = 'Asia/Kolkata';

export function rupees(paise) {
    if (paise === null || paise === undefined) {
        return '–';
    }
    const amount = paise / 100;
    return '₹' + amount.toLocaleString('en-IN', {minimumFractionDigits: paise % 100 ? 2 : 0,
                                                 maximumFractionDigits: 2});
}

export function showTime(instant) {
    return new Date(instant).toLocaleTimeString('en-IN', {hour: 'numeric', minute: '2-digit', timeZone: ZONE});
}

export function showDateTime(instant) {
    return new Date(instant).toLocaleString('en-IN', {weekday: 'short', day: 'numeric', month: 'short',
                                                      hour: 'numeric', minute: '2-digit', timeZone: ZONE});
}

export function dayLabel(isoDate) {
    const date = new Date(isoDate + 'T00:00:00+05:30');
    return {
        weekday: date.toLocaleDateString('en-IN', {weekday: 'short', timeZone: ZONE}),
        day: date.toLocaleDateString('en-IN', {day: 'numeric', timeZone: ZONE}),
        month: date.toLocaleDateString('en-IN', {month: 'short', timeZone: ZONE}),
    };
}

/** Today's date in IST, as the API's date parameters expect. */
export function todayIst() {
    return new Date(Date.now() + 5.5 * 3600000).toISOString().slice(0, 10);
}

