// Small DOM helpers shared by the admin panel and the customer site. No framework on purpose: it's a prototype.

/**
 * h('button', {class: 'primary', onclick: save}, 'Save'). Attributes starting with "on" become listeners;
 * null/false children are skipped, arrays are flattened.
 */
export function h(tag, attrs = {}, ...children) {
    const element = document.createElement(tag);
    for (const [name, value] of Object.entries(attrs || {})) {
        if (value === null || value === undefined || value === false) {
            continue;
        }
        if (name.startsWith('on')) {
            element.addEventListener(name.slice(2), value);
        } else if (value === true) {
            element.setAttribute(name, '');
        } else {
            element.setAttribute(name, value);
        }
    }
    for (const child of children.flat(Infinity)) {
        if (child === null || child === undefined || child === false) {
            continue;
        }
        element.append(child instanceof Node ? child : document.createTextNode(String(child)));
    }
    return element;
}

export function mount(container, ...children) {
    container.replaceChildren(...children.flat(Infinity).filter(Boolean));
}

// ---- feedback ----

function toastHost() {
    let host = document.querySelector('.toasts');
    if (!host) {
        host = h('div', {class: 'toasts', role: 'status', 'aria-live': 'polite'});
        document.body.append(host);
    }
    return host;
}

export function toast(message, kind = 'info') {
    const note = h('div', {class: `toast ${kind}`}, message);
    toastHost().append(note);
    setTimeout(() => note.remove(), kind === 'error' ? 7000 : 3500);
}

/** Shows an API error the way the API describes it: the detail, plus the stable code. */
export function showError(error) {
    const code = error.code ? ` (${error.code})` : '';
    toast((error.message || 'Something went wrong') + code, 'error');
    console.error(error);
}

/** Runs an async action with the button disabled, reporting errors instead of throwing them. */
export async function withBusy(button, action) {
    button.disabled = true;
    button.classList.add('busy');
    try {
        return await action();
    } catch (error) {
        showError(error);
        return undefined;
    } finally {
        button.disabled = false;
        button.classList.remove('busy');
    }
}

export function loading(text = 'Loading…') {
    return h('p', {class: 'muted loading'}, text);
}

export function empty(text) {
    return h('p', {class: 'empty'}, text);
}

export function badge(text, kind = '') {
    return h('span', {class: `badge ${kind}`}, text);
}

// ---- dialogs ----

/** Resolves true when the user confirms. */
export function confirmDialog(message, confirmLabel = 'Confirm', danger = false) {
    return new Promise(resolve => {
        const dialog = h('dialog', {class: 'dialog'},
            h('form', {method: 'dialog'},
                h('p', {}, message),
                h('div', {class: 'actions'},
                    h('button', {value: 'cancel', class: 'ghost'}, 'Cancel'),
                    h('button', {value: 'ok', class: danger ? 'danger' : 'primary'}, confirmLabel))));
        dialog.addEventListener('close', () => {
            resolve(dialog.returnValue === 'ok');
            dialog.remove();
        });
        document.body.append(dialog);
        dialog.showModal();
    });
}

/**
 * A form in a dialog. fields: [{name, label, type = 'text' | 'number' | 'select' | 'checkbox' | 'textarea' |
 * 'date' | 'datetime-local', options: [[value, label]], required, hint, step, min}]. Resolves with the values
 * keyed by name, or null when cancelled. onSubmit may throw to keep the dialog open (e.g. an API error).
 */
export function formDialog(title, fields, initial = {}, onSubmit = async values => values) {
    return new Promise(resolve => {
        const inputs = {};
        const rows = fields.map(field => {
            const input = inputFor(field, initial[field.name]);
            inputs[field.name] = input;
            if (field.type === 'checkbox') {
                return h('label', {class: 'check'}, input, field.label, field.hint && h('small', {}, field.hint));
            }
            return h('label', {}, h('span', {}, field.label), input, field.hint && h('small', {}, field.hint));
        });
        const submit = h('button', {type: 'submit', class: 'primary'}, 'Save');
        const form = h('form', {class: 'stack'},
            h('h2', {}, title), rows,
            h('div', {class: 'actions'},
                h('button', {type: 'button', class: 'ghost', onclick: () => dialog.close()}, 'Cancel'), submit));
        const dialog = h('dialog', {class: 'dialog wide'}, form);
        let result = null;
        form.addEventListener('submit', async event => {
            event.preventDefault();
            const values = {};
            for (const field of fields) {
                values[field.name] = valueOf(field, inputs[field.name]);
            }
            const saved = await withBusy(submit, () => onSubmit(values));
            if (saved !== undefined) {
                result = saved;
                dialog.close();
            }
        });
        dialog.addEventListener('close', () => {
            resolve(result);
            dialog.remove();
        });
        document.body.append(dialog);
        dialog.showModal();
    });
}

function inputFor(field, value) {
    const common = {name: field.name, required: field.required, placeholder: field.placeholder};
    switch (field.type) {
        case 'select':
            return h('select', common, field.options.map(([optionValue, label]) =>
                h('option', {value: optionValue, selected: String(optionValue) === String(value ?? '')}, label)));
        case 'checkbox':
            return h('input', {...common, type: 'checkbox', checked: Boolean(value)});
        case 'textarea':
            return Object.assign(h('textarea', {...common, rows: field.rows || 6}), {value: value ?? ''});
        default:
            return Object.assign(h('input', {...common, type: field.type || 'text', step: field.step,
                                             min: field.min, max: field.max}), {value: value ?? ''});
    }
}

function valueOf(field, input) {
    if (field.type === 'checkbox') {
        return input.checked;
    }
    if (field.type === 'number') {
        return input.value === '' ? null : Number(input.value);
    }
    return input.value.trim() === '' ? null : input.value.trim();
}

