/* Design tokens and components shared by both prototypes. Each app sets its accent with data-app on <body>. */

:root {
    --bg: #f6f7f9;
    --surface: #ffffff;
    --surface-2: #f0f2f5;
    --border: #dde1e7;
    --text: #1b1f24;
    --muted: #5d6673;
    --accent: #4f46e5;
    --accent-text: #ffffff;
    --accent-soft: #eceafd;
    --ok: #15803d;
    --ok-soft: #dcfce7;
    --warn: #b45309;
    --warn-soft: #fef3c7;
    --danger: #b91c1c;
    --danger-soft: #fee2e2;
    --radius: 10px;
    --shadow: 0 1px 2px rgb(16 24 40 / 6%), 0 4px 16px rgb(16 24 40 / 6%);
    --font: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
    color-scheme: light;
}

body[data-app="shop"] {
    --accent: #e11d48;
    --accent-soft: #ffe4ea;
}

@media (prefers-color-scheme: dark) {
    :root {
        --bg: #0f1217;
        --surface: #171b22;
        --surface-2: #1f242d;
        --border: #2c333e;
        --text: #e8ebf0;
        --muted: #9aa4b2;
