    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: var(--radius);
    box-shadow: var(--shadow);
    padding: 1.1rem 1.2rem;
}

.card + .card { margin-top: 1rem; }

.table-wrap { overflow-x: auto; }

table {
    width: 100%;
    border-collapse: collapse;
    font-size: .92rem;
}

th, td {
    padding: .6rem .7rem;
    border-bottom: 1px solid var(--border);
    text-align: left;
    vertical-align: middle;
}

th {
    color: var(--muted);
    font-weight: 600;
    font-size: .8rem;
    text-transform: uppercase;
    letter-spacing: .03em;
}

td.num, th.num { text-align: right; font-variant-numeric: tabular-nums; }

tr.inactive td { color: var(--muted); }

.badge {
    display: inline-block;
    padding: .1rem .5rem;
    border-radius: 999px;
    background: var(--surface-2);
    color: var(--muted);
    font-size: .78rem;
    font-weight: 600;
    letter-spacing: .02em;
}

.badge.ok { background: var(--ok-soft); color: var(--ok); }
.badge.warn { background: var(--warn-soft); color: var(--warn); }
.badge.danger { background: var(--danger-soft); color: var(--danger); }
.badge.accent { background: var(--accent-soft); color: var(--accent); }

/* ---- dialogs and toasts ---- */

.dialog {
    width: min(92vw, 420px);
    padding: 1.3rem;
    border: 1px solid var(--border);
    border-radius: var(--radius);
    background: var(--surface);
    color: var(--text);
    box-shadow: var(--shadow);
}

.dialog.wide { width: min(92vw, 560px); }

.dialog::backdrop { background: rgb(10 12 16 / 45%); }

.dialog .actions {
    display: flex;
    justify-content: flex-end;
    gap: .5rem;
    margin-top: .5rem;
}

.toasts {
    position: fixed;
    right: 1rem;
    bottom: 1rem;
    z-index: 100;
    display: grid;
    gap: .5rem;
    max-width: min(92vw, 380px);
}

.toast {
    padding: .7rem 1rem;
    border-radius: 8px;
    background: var(--text);
    color: var(--bg);
    box-shadow: var(--shadow);
    animation: rise .2s ease-out;
}

.toast.error { background: var(--danger); color: #fff; }
.toast.ok { background: var(--ok); color: #fff; }

@keyframes rise { from { transform: translateY(8px); opacity: 0; } }

/* ---- seat map (both apps) ---- */

.screen-edge {
    margin: 0 auto 1.2rem;
    width: 70%;
    padding: .3rem;
    border-top: 4px solid var(--accent);
    border-radius: 50% 50% 0 0 / 14px 14px 0 0;
    color: var(--muted);
    font-size: .75rem;
    text-align: center;
    letter-spacing: .3em;
}

.seat-map {
    display: grid;
    gap: 6px;
    justify-content: center;
    overflow-x: auto;
    padding-bottom: .5rem;
}

.seat {
    width: 30px;
    height: 28px;
    padding: 0;
    justify-content: center;
    border-radius: 6px 6px 3px 3px;
    font-size: .62rem;
    font-weight: 600;
}

.seat.available { border-color: var(--ok); color: var(--ok); }
.seat.available:hover { background: var(--ok-soft); }
.seat.selected { background: var(--accent); border-color: var(--accent); color: var(--accent-text); }
.seat.held, .seat.booked { background: var(--surface-2); color: var(--muted); border-color: var(--border); }
.seat.blocked { background: repeating-linear-gradient(45deg, var(--surface-2) 0 4px, var(--border) 4px 6px);
                color: transparent; border-color: var(--border); }
.seat.wheelchair::after { content: "♿"; font-size: .6rem; margin-left: 1px; }
.seat.premium.available { border-width: 2px; }
.seat.recliner.available { border-width: 2px; border-style: double; }

.legend {
    display: flex;
    flex-wrap: wrap;
    gap: 1rem;
    justify-content: center;
    margin-top: .8rem;
    font-size: .82rem;
    color: var(--muted);
}

.legend .seat { width: 18px; height: 16px; cursor: default; }

.legend span { display: inline-flex; align-items: center; gap: .35rem; }

@media (max-width: 640px) {
    .seat { width: 24px; height: 22px; font-size: .5rem; }
    .seat-map { gap: 4px; justify-content: start; }
}

