import {h} from './ui.js';

/**
 * Draws seats on the screen's grid (aisles are simply empty cells).
 *
 * @param layout {gridRows, gridCols, seats: [{id, label, row, col, category, type, status}]}
 *        status is AVAILABLE, HELD, BOOKED or BLOCKED; category is the category code
 * @param options.selected a Set of seat ids drawn as selected
 * @param options.canSelect seat => boolean; seats that can't be selected are disabled
 * @param options.onToggle seat => void
 */
export function seatMap(layout, {selected = new Set(), canSelect = () => false, onToggle = () => {}} = {}) {
    const grid = h('div', {class: 'seat-map', role: 'group', 'aria-label': 'Seats'});
    grid.style.gridTemplateColumns = `repeat(${layout.gridCols}, max-content)`;
    for (const seat of layout.seats) {
        const status = (seat.status || 'AVAILABLE').toLowerCase();
        const classes = ['seat', status, (seat.category || '').toLowerCase(),
                         seat.type === 'WHEELCHAIR' ? 'wheelchair' : '',
                         selected.has(seat.id) ? 'selected' : ''].filter(Boolean).join(' ');
        const button = h('button', {
            type: 'button',
            class: classes,
            disabled: !canSelect(seat),
            title: `${seat.label} · ${seat.category} · ${status}`,
            'aria-pressed': selected.has(seat.id) ? 'true' : 'false',
            onclick: () => onToggle(seat),
        }, status === 'blocked' ? '' : seat.label);
        button.style.gridRow = seat.row;
        button.style.gridColumn = seat.col;
        grid.append(button);
    }
    return h('div', {},
        h('div', {class: 'screen-edge'}, 'SCREEN'),
        grid,
        h('div', {class: 'legend'},
            legendItem('available', 'Available'),
            legendItem('selected', 'Selected'),
            legendItem('booked', 'Taken'),
            legendItem('blocked', 'Blocked')));
}

function legendItem(kind, label) {
    return h('span', {}, h('span', {class: `seat ${kind}`}), label);
}

