import {api, ApiError, baseUrl, dayLabel, newKey, rupees, saveIdentity, showDateTime, showTime, storedIdentity}
    from '../shared/api.js';
import {badge, confirmDialog, empty, formDialog, h, loading, mount, showError, toast, withBusy} from '../shared/ui.js';
import {seatMap} from '../shared/seatmap.js';

const IDENTITY_KEY = 'moviebooking.customer';
const CITY_KEY = 'moviebooking.cityId';
const MAX_SEATS = 10;
const SLOTS = [['MORNING', 'Morning'], ['AFTERNOON', 'Afternoon'], ['EVENING', 'Evening'], ['NIGHT', 'Night']];

let customer = storedIdentity(IDENTITY_KEY, {role: 'CUSTOMER', name: 'Asha Rao', email: 'asha@example.com',
                                             phone: '+919800000001'});
const app = document.getElementById('app');
const call = (path, options) => api(path, customer, options);

// timers belong to the page that started them and stop when the customer navigates away
let timers = [];

function every(ms, task) {
    timers.push(setInterval(task, ms));
}

// ---- header ----

async function loadCities() {
    const select = document.getElementById('city');
    try {
        const cities = await call('/api/v1/cities');
        if (!cities.length) {
            mount(select, h('option', {}, 'No cities yet'));
            return;
        }
        const saved = Number(localStorage.getItem(CITY_KEY));
        const current = cities.some(city => city.id === saved) ? saved : cities[0].id;
        localStorage.setItem(CITY_KEY, current);
        mount(select, cities.map(city => h('option', {value: city.id, selected: city.id === current}, city.name)));
    } catch (error) {
        showError(error);
    }
}

document.getElementById('city').addEventListener('change', event => {
    localStorage.setItem(CITY_KEY, event.target.value);
    location.hash = '#/';
    render();
});

function renderProfile() {
    document.getElementById('profile').textContent = `👤 ${customer.name || 'Guest'}`;
}

document.getElementById('profile').addEventListener('click', async () => {
    const saved = await formDialog('Your details', [
        {name: 'name', label: 'Name'},
        {name: 'email', label: 'Email', type: 'email', hint: 'Tickets and refunds are emailed here (see Mailpit).'},
        {name: 'phone', label: 'Phone', hint: 'The SMS goes to the app log.'},
        {name: 'fresh', label: 'Start over as a new customer', type: 'checkbox',
         hint: 'A new customer id: handy for trying two customers in two windows.'},
    ], customer);
    if (!saved) {
        return;
    }
    customer = {...customer, name: saved.name, email: saved.email, phone: saved.phone,
                id: saved.fresh ? crypto.randomUUID() : customer.id};
    saveIdentity(IDENTITY_KEY, customer);
    renderProfile();
    toast(saved.fresh ? 'You are now a new customer' : 'Details saved', 'ok');
    render();
});

// ---- pages ----

const cityId = () => localStorage.getItem(CITY_KEY);

async function homePage() {
    mount(app, h('h1', {}, 'Now showing'), loading());
    if (!cityId()) {
        mount(app, h('h1', {}, 'Now showing'), empty('No cities yet. Add one in the admin panel.'));
        return;
    }
    const movies = await call(`/api/v1/cities/${cityId()}/movies`);
    mount(app,
        h('h1', {}, 'Now showing'),
        movies.length
            ? h('div', {class: 'movies'}, movies.map(movie =>
                h('a', {class: 'movie', href: `#/movie/${movie.id}`},
                    h('div', {class: 'poster', style: `background: ${posterColour(movie.title)}`}, movie.title),
                    h('div', {}, h('b', {}, movie.title), h('br'),
                        h('small', {}, `${movie.certification} · ${duration(movie.durationMin)}`)))))
            : empty('Nothing is showing in this city in the next 7 days.'));
}

async function moviePage(movieId, params) {
    mount(app, loading());
    const [movie, dates] = await Promise.all([
        call(`/api/v1/movies/${movieId}`),
        call(`/api/v1/movies/${movieId}/dates?cityId=${cityId()}`)]);
    if (!dates.length) {
        mount(app, movieHeader(movie), empty('No shows for this movie in your city this week.'));
        return;
    }
    const date = dates.includes(params.get('date')) ? params.get('date') : dates[0];
    const slots = new Set((params.get('slot') || '').split(',').filter(Boolean));

    const go = changes => {
        const next = new URLSearchParams({date, slot: [...slots].join(','), ...changes});
        location.hash = `#/movie/${movieId}?${next}`;
    };
    const query = new URLSearchParams({cityId: cityId(), date});
    if (slots.size) {
        query.set('slot', [...slots].join(','));
    }
    const listing = await call(`/api/v1/movies/${movieId}/shows?${query}`);

    mount(app,
        movieHeader(movie),
        h('div', {class: 'dates', role: 'group', 'aria-label': 'Date'}, dates.map(day => {
            const label = dayLabel(day);
            return h('button', {class: 'date', 'aria-pressed': String(day === date), onclick: () => go({date: day})},
                h('small', {}, label.weekday), h('b', {}, label.day), h('small', {}, label.month));
        })),
        h('div', {class: 'chips', style: 'margin: 1rem 0'}, SLOTS.map(([slot, label]) =>
            h('button', {class: 'chip small', 'aria-pressed': String(slots.has(slot)), onclick: () => {
                slots.has(slot) ? slots.delete(slot) : slots.add(slot);
                go({});
            }}, label))),
        listing.theaters.length
            ? listing.theaters.map(({theater, shows}) => h('section', {class: 'card theater'},
                h('div', {}, h('h3', {}, theater.name), h('small', {}, theater.area || '')),
                h('div', {class: 'chips'}, shows.map(show => h('button', {
                    class: `showtime ${show.availability.toLowerCase()}`,
                    disabled: show.availability === 'SOLD_OUT',
                    onclick: () => {
                        sessionStorage.setItem(`show.${show.showId}`, JSON.stringify(
                            {movie: movie.title, theater: theater.name, startTime: show.startTime}));
                        location.hash = `#/show/${show.showId}`;
                    },
                }, h('b', {}, showTime(show.startTime)),
                    h('small', {}, `${show.language} · ${show.format} · from ${rupees(show.priceFromPaise)}`),
                    h('small', {}, availabilityText(show)))))))
            : empty('No showtimes match. Try another time of day.'));
}

async function seatsPage(showId) {
    mount(app, loading());
    const context = JSON.parse(sessionStorage.getItem(`show.${showId}`) || 'null');
    let map = await call(`/api/v1/shows/${showId}/seats`);
    const selected = new Set();
    let couponCode = '';
    let holdKey = newKey();

    const categories = new Map(map.categories.map(category => [category.id, category]));
    const seats = () => map.seats.map(seat => ({...seat, id: seat.seatId,
                                                category: categories.get(seat.categoryId)?.code}));

    const mapHost = h('div');
    const summaryHost = h('div');

    const draw = () => {
        // a seat someone else just took can't stay selected
        for (const seat of map.seats) {
            if (seat.status !== 'AVAILABLE') {
                selected.delete(seat.seatId);
            }
        }
        mount(mapHost, seatMap({...map, seats: seats()}, {
            selected,
            canSelect: seat => seat.status === 'AVAILABLE',
            onToggle: seat => {
                if (selected.has(seat.id)) {
                    selected.delete(seat.id);
                } else if (selected.size >= MAX_SEATS) {
                    toast(`At most ${MAX_SEATS} seats per booking`);
                } else {
                    selected.add(seat.id);
                }
                draw();
            },
        }));
        drawSummary();
    };

    const drawSummary = () => {
        const chosen = map.seats.filter(seat => selected.has(seat.seatId));
        const estimate = chosen.reduce((sum, seat) => sum + categories.get(seat.categoryId).pricePaise, 0);
        const coupon = h('input', {placeholder: 'Coupon code (optional)', value: couponCode,
                                   oninput: event => couponCode = event.target.value.trim()});
        const hold = h('button', {class: 'primary', disabled: !chosen.length}, `Hold ${chosen.length || ''} seat${chosen.length === 1 ? '' : 's'}`);
        hold.addEventListener('click', () => withBusy(hold, async () => {
            try {
                const booking = await call('/api/v1/bookings', {method: 'POST', key: holdKey, body: {
                    showId: Number(showId), seatIds: [...selected], couponCode: couponCode || null}});
                location.hash = `#/booking/${booking.bookingId}`;
            } catch (error) {
                if (error.status !== 0) {
                    holdKey = newKey();   // a real answer: the next try is a new request
                }
                if (error.code === 'ACTIVE_HOLD_EXISTS' && error.problem.bookingId) {
                    toast('You already have seats on hold for this show; here they are.');
                    location.hash = `#/booking/${error.problem.bookingId}`;
                    return;
                }
                if (error.code === 'SEATS_UNAVAILABLE') {
                    map = await call(`/api/v1/shows/${showId}/seats`);
                    draw();
                }
                throw error;
            }
        }));
        mount(summaryHost, h('aside', {class: 'card summary stack'},
            h('h2', {}, 'Your seats'),
            chosen.length
                ? h('div', {class: 'seat-list'}, chosen.map(seat => h('span', {class: 'seat-pill'}, seat.label)))
                : h('p', {class: 'muted'}, 'Pick up to 10 seats on the map.'),
            chosen.length > 0 && h('div', {class: 'lines'},
                h('div', {}, h('span', {}, 'Tickets'), h('span', {}, rupees(estimate))),
                h('small', {}, 'Plus a ₹20 convenience fee a seat and GST; the exact total comes with the hold.')),
            coupon,
            hold,
            h('small', {}, 'Held seats are yours for 8 minutes while you pay.')));
    };

    mount(app,
        h('div', {class: 'row'},
            h('div', {},
                h('h1', {}, context ? context.movie : `Show ${showId}`),
                h('p', {class: 'muted'}, context ? `${context.theater} · ${map.screen} · ${showDateTime(context.startTime)}`
                                                 : map.screen))),
        h('div', {class: 'booking-layout'},
            h('section', {class: 'card'},
                mapHost,
                h('div', {class: 'legend'}, map.categories.map(category =>
                    h('span', {}, `${category.name} ${rupees(category.pricePaise)}`)))),
            summaryHost));
    draw();

    // other customers are booking too: keep the map fresh
    every(8000, async () => {
        try {
            map = await call(`/api/v1/shows/${showId}/seats`);
            draw();
        } catch (error) {
            // a missed refresh is fine; the next one will catch up
        }
    });
}

async function bookingPage(bookingId) {
    mount(app, loading());
    const booking = await call(`/api/v1/bookings/${bookingId}`);

    const header = h('div', {class: 'row'},
        h('div', {},
            h('h1', {}, booking.movieTitle),
            h('p', {class: 'muted'}, `${booking.theaterName} · ${showDateTime(booking.showStartTime)}`)),
        h('span', {class: 'spacer'}),
        statusBadge(booking.status));

    const main = [];
    const side = [priceCard(booking)];

    switch (booking.status) {
        case 'HELD':
            main.push(seatsCard(booking), payCard(booking));
            side.unshift(holdCard(booking));
            break;
        case 'PAYMENT_PENDING':
            main.push(seatsCard(booking), h('section', {class: 'card'},
                h('h2', {}, 'Waiting for your bank…'),
                h('p', {class: 'muted loading'}, 'The payment is being processed. This page updates by itself.')));
            every(2000, async () => {
                const latest = await call(`/api/v1/bookings/${bookingId}`).catch(() => null);
                if (latest && latest.status !== 'PAYMENT_PENDING') {
                    toast(latest.status === 'CONFIRMED' ? 'Payment received. Enjoy the show!' : 'Payment finished',
                          latest.status === 'CONFIRMED' ? 'ok' : 'info');
                    render();
                }
            });
            break;
        case 'CONFIRMED':
            main.push(ticketCard(booking), cancelCard(booking));
            break;
        default:
            main.push(seatsCard(booking), h('section', {class: 'card'}, h('p', {}, closedMessage(booking))));
    }
    if (booking.cancellations.length) {
        main.push(cancellationsCard(booking));
    }
    if (booking.payment) {
        side.push(paymentCard(booking));
        if (booking.payment.refunds.some(refund => refund.status === 'INITIATED')) {
            every(2500, () => render());         // show the refund completing
        }
    }

    mount(app, header, h('div', {class: 'booking-layout'}, h('div', {class: 'stack'}, main),
                         h('div', {class: 'stack summary'}, side)));
}

async function historyPage(params) {
    const view = params.get('view') || 'UPCOMING';
    const page = Number(params.get('page') || 0);
    mount(app, h('h1', {}, 'My bookings'), loading());
    const history = await call(`/api/v1/bookings?view=${view}&page=${page}&size=10`);
    const tab = (value, label) => h('button', {'aria-pressed': String(view === value),
                                               onclick: () => location.hash = `#/bookings?view=${value}`}, label);
    mount(app,
        h('h1', {}, 'My bookings'),
        h('div', {class: 'tabs', style: 'margin-bottom: 1rem'},
            tab('UPCOMING', 'Upcoming'), tab('PAST', 'Past'), tab('CANCELLED', 'Cancelled')),
        history.items.length
            ? h('div', {class: 'stack'}, history.items.map(item =>
                h('a', {class: 'card history-item', href: `#/booking/${item.bookingId}`},
                    h('div', {style: 'flex: 1; min-width: 14rem'},
                        h('b', {}, item.movieTitle), h('br'),
                        h('small', {}, `${item.theaterName} · ${showDateTime(item.showStartTime)}`)),
                    h('div', {class: 'seat-list'},
                        item.seats.map(label => h('span', {class: 'seat-pill'}, label)),
                        item.cancelledSeats.map(label => h('span', {class: 'seat-pill cancelled'}, label))),
                    h('b', {}, rupees(item.totalPaise)),
                    h('small', {class: 'muted'}, item.bookingRef))))
            : empty(view === 'UPCOMING' ? 'No upcoming bookings. Time for a movie?' : 'Nothing here yet.'),
        history.totalPages > 1 && h('div', {class: 'row end', style: 'margin-top: 1rem'},
            h('button', {disabled: page === 0, onclick: () => location.hash = `#/bookings?view=${view}&page=${page - 1}`},
                '← Newer'),
            h('span', {class: 'muted'}, `Page ${page + 1} of ${history.totalPages}`),
            h('button', {disabled: page + 1 >= history.totalPages,
                         onclick: () => location.hash = `#/bookings?view=${view}&page=${page + 1}`}, 'Older →')));
}

// ---- booking page parts ----

function holdCard(booking) {
    const clock = h('div', {class: 'countdown'});
    const tick = () => {
        const left = Math.max(0, new Date(booking.holdExpiresAt) - Date.now());
        const minutes = Math.floor(left / 60000);
        const seconds = Math.floor(left / 1000) % 60;
        clock.textContent = `${minutes}:${String(seconds).padStart(2, '0')}`;
        clock.classList.toggle('low', left < 60000);
        if (left === 0) {
            clock.textContent = 'Expired';
        }
    };
    tick();
    every(1000, tick);

    const release = h('button', {class: 'ghost'}, 'Let these seats go');
    release.addEventListener('click', async () => {
        if (await confirmDialog('Release these seats? Someone else can take them straight away.', 'Release')) {
            await withBusy(release, async () => {
                await call(`/api/v1/bookings/${booking.bookingId}/release`, {method: 'POST'});
                toast('Seats released');
                history.back();
            });
        }
    });
    return h('section', {class: 'card stack'},
        h('div', {}, h('small', {}, 'Seats held for'), clock),
        couponForm(booking),
        release);
}

function couponForm(booking) {
    const input = h('input', {placeholder: 'Coupon code', value: booking.coupon || ''});
    const apply = h('button', {}, booking.coupon ? 'Change' : 'Apply');
    apply.addEventListener('click', () => withBusy(apply, async () => {
        if (!input.value.trim()) {
            return;
        }
        await call(`/api/v1/bookings/${booking.bookingId}/coupon`, {method: 'PUT', body: {code: input.value.trim()}});
        toast('Coupon applied', 'ok');
        render();
    }));
    const remove = booking.coupon && h('button', {class: 'ghost small'}, 'Remove');
    remove?.addEventListener('click', () => withBusy(remove, async () => {
        await call(`/api/v1/bookings/${booking.bookingId}/coupon`, {method: 'DELETE'});
        render();
    }));
    return h('div', {class: 'stack'},
        h('div', {class: 'row'}, input, apply),
        booking.coupon && h('div', {class: 'row'}, badge(`${booking.coupon} applied`, 'ok'), remove));
}

function payCard(booking) {
    let method = 'UPI';
    let payKey = newKey();
    const fieldsHost = h('div', {class: 'stack'});
    const inputs = {};
    const input = (name, attrs) => (inputs[name] = h('input', {name, ...attrs}));
    const select = (name, options) => (inputs[name] = h('select', {name},
        options.map(option => h('option', {value: option}, option))));

    const methods = {
        UPI: () => [h('label', {}, 'UPI ID', input('vpa', {value: 'asha@okbank', autocomplete: 'off'}))],
        CARD: () => [
            h('label', {}, 'Card number', input('number', {value: '4242 4242 4242 4242', inputmode: 'numeric'})),
            h('div', {class: 'grid-2'},
                h('label', {}, 'Expiry (MM/YY)', input('expiry', {value: '12/30'})),
                h('label', {}, 'CVV', input('cvv', {value: '123', inputmode: 'numeric'}))),
            h('label', {}, 'Name on card', input('holderName', {value: customer.name || ''})),
            h('small', {}, '4242 4242 4242 4242 passes the Luhn check; change a digit to see a validation error.')],
        NET_BANKING: () => [h('label', {}, 'Bank', select('bankCode', ['HDFC', 'ICICI', 'SBI', 'AXIS', 'KOTAK']))],
        WALLET: () => [h('label', {}, 'Wallet', select('provider', ['PAYTM', 'PHONEPE', 'AMAZONPAY']))],
    };
    const tabs = h('div', {class: 'tabs', role: 'group', 'aria-label': 'Payment method'});
    const drawMethod = () => {
        mount(tabs, [['UPI', 'UPI'], ['CARD', 'Card'], ['NET_BANKING', 'Net banking'], ['WALLET', 'Wallet']]
            .map(([value, label]) => h('button', {type: 'button', 'aria-pressed': String(method === value),
                                                  onclick: () => { method = value; drawMethod(); }}, label)));
        mount(fieldsHost, methods[method]());
    };
    drawMethod();

    const outcome = h('select', {},
        h('option', {value: 'SUCCESS'}, 'The payment goes through'),
        h('option', {value: 'FAILURE'}, 'The bank declines it'),
        h('option', {value: 'DELAYED'}, 'The bank is slow (answers in ~15 s)'));

    const pay = h('button', {class: 'primary'}, `Pay ${rupees(booking.price.totalPaise)}`);
    pay.addEventListener('click', () => withBusy(pay, async () => {
        try {
            const result = await call(`/api/v1/bookings/${booking.bookingId}/payments`, {method: 'POST', key: payKey,
                body: {details: paymentDetails(method, inputs), simulate: outcome.value}});
            if (result.paymentStatus === 'FAILED') {
                toast(`Payment declined: ${result.failureReason}. The seats have been released.`, 'error');
            } else if (result.paymentStatus === 'SUCCESS') {
                toast('Booked! Your tickets are on their way by email.', 'ok');
            }
            render();
        } catch (error) {
            if (error.status !== 0) {
                payKey = newKey();   // fixed details are a new request; only a lost answer is retried as-is
            }
            throw error;
        }
    }));

    return h('section', {class: 'card stack'},
        h('h2', {}, 'Pay'),
        tabs,
        fieldsHost,
        h('label', {}, h('span', {}, 'Simulated bank'), outcome,
            h('small', {}, 'The gateway is simulated; pick what it should do.')),
        pay);
}

function paymentDetails(method, inputs) {
    const value = name => inputs[name].value.trim();
    switch (method) {
        case 'UPI':
            return {type: 'UPI', vpa: value('vpa')};
        case 'CARD': {
            const [month, year] = value('expiry').split('/').map(part => Number(part.trim()));
            return {type: 'CARD', number: value('number'), expiryMonth: month, expiryYear: 2000 + (year % 100),
                    cvv: value('cvv'), holderName: value('holderName')};
        }
        case 'NET_BANKING':
            return {type: 'NET_BANKING', bankCode: value('bankCode')};
        default:
            return {type: 'WALLET', provider: value('provider')};
    }
}

function ticketCard(booking) {
    const active = booking.seats.filter(seat => seat.status === 'ACTIVE');
    return h('section', {class: 'card ticket stack'},
        h('div', {class: 'row'},
            h('div', {}, h('small', {}, 'Booking reference'), h('div', {class: 'ref'}, booking.bookingRef)),
            h('span', {class: 'spacer'}),
            h('div', {}, h('small', {}, 'Show time'), h('div', {}, h('b', {}, showDateTime(booking.showStartTime))))),
        h('div', {class: 'seat-list'}, active.map(seat => h('span', {class: 'seat-pill'}, seat.label))),
        h('small', {}, 'Show this reference at the counter. A reminder arrives 2 hours before the show.'));
}

function cancelCard(booking) {
    const active = booking.seats.filter(seat => seat.status === 'ACTIVE');
    const chosen = new Set(active.map(seat => seat.seatId));
    const quoteHost = h('div');
    let cancelKey = newKey();

    const quote = async () => {
        mount(quoteHost, loading('Working out your refund…'));
        try {
            const query = chosen.size === active.length ? '' : `?${[...chosen].map(id => `seatIds=${id}`).join('&')}`;
            const refund = await call(`/api/v1/bookings/${booking.bookingId}/refund-quote${query}`);
            const cancel = h('button', {class: 'danger'}, `Cancel ${refund.seats.join(', ')}`);
            cancel.addEventListener('click', async () => {
                const question = refund.refundPaise
                    ? `Cancel ${refund.seats.join(', ')} and get ${rupees(refund.refundPaise)} back?`
                    : `Cancel ${refund.seats.join(', ')}? Nothing will be refunded.`;
                if (!await confirmDialog(question, 'Cancel seats', true)) {
                    return;
                }
                await withBusy(cancel, async () => {
                    try {
                        const body = chosen.size === active.length ? {} : {seatIds: [...chosen]};
                        const result = await call(`/api/v1/bookings/${booking.bookingId}/cancellations`,
                                                  {method: 'POST', key: cancelKey, body});
                        toast(result.refundPaise ? `Cancelled. ${rupees(result.refundPaise)} is on its way back.`
                                                 : 'Cancelled.', 'ok');
                        render();
                    } catch (error) {
                        if (error.status !== 0) {
                            cancelKey = newKey();
                        }
                        throw error;
                    }
                });
            });
            mount(quoteHost, h('div', {class: 'stack'},
                h('div', {class: 'lines'},
                    h('div', {}, h('span', {}, `Refund (${refund.refundPercent}% of the ticket price)`),
                        h('b', {}, rupees(refund.refundPaise))),
                    h('div', {}, h('span', {}, 'Not refunded'), h('span', {}, rupees(refund.retainedPaise)))),
                cancel));
        } catch (error) {
            mount(quoteHost, h('p', {class: 'muted'}, error.code === 'CANCELLATION_CLOSED'
                ? 'Cancellation has closed: it ends 30 minutes before the show.' : error.message));
        }
    };

    const checkboxes = active.map(seat => h('label', {class: 'check'},
        h('input', {type: 'checkbox', checked: true, onchange: event => {
            event.target.checked ? chosen.add(seat.seatId) : chosen.delete(seat.seatId);
            chosen.size ? quote() : mount(quoteHost, h('p', {class: 'muted'}, 'Pick at least one seat.'));
        }}), seat.label));
    quote();
    return h('section', {class: 'card stack'},
        h('h2', {}, 'Cancel seats'),
        h('div', {class: 'row'}, checkboxes),
        quoteHost);
}

function seatsCard(booking) {
    return h('section', {class: 'card stack'},
        h('h2', {}, 'Seats'),
        h('div', {class: 'seat-list'}, booking.seats.map(seat =>
            h('span', {class: `seat-pill ${seat.status === 'CANCELLED' ? 'cancelled' : ''}`}, seat.label))));
}

function cancellationsCard(booking) {
    return h('section', {class: 'card'},
        h('h2', {}, 'Cancellations'),
        h('div', {class: 'table-wrap'}, h('table', {},
            h('thead', {}, h('tr', {}, h('th', {}, 'When'), h('th', {}, 'Seats'), h('th', {}, 'Why'),
                                    h('th', {class: 'num'}, 'Refund'))),
            h('tbody', {}, booking.cancellations.map(cancellation => h('tr', {},
                h('td', {}, showDateTime(cancellation.cancelledAt)),
                h('td', {}, cancellation.seats.join(', ')),
                h('td', {}, cancellation.reason === 'SHOW_CANCELLED' ? 'Show cancelled' : 'You cancelled'),
                h('td', {class: 'num'}, `${rupees(cancellation.refundPaise)} (${cancellation.refundPercent}%)`)))))));
}

function priceCard(booking) {
    const price = booking.price;
    return h('section', {class: 'card stack'},
        h('h2', {}, 'Price'),
        h('div', {class: 'lines'},
            h('div', {}, h('span', {}, `Tickets (${booking.seats.length})`), h('span', {}, rupees(price.subtotalPaise))),
            price.discountPaise > 0 && h('div', {}, h('span', {}, `Coupon ${booking.coupon || ''}`),
                                         h('span', {}, '−' + rupees(price.discountPaise))),
            h('div', {}, h('span', {}, 'Convenience fee'), h('span', {}, rupees(price.feePaise))),
            h('div', {}, h('span', {}, 'GST'), h('span', {}, rupees(price.taxPaise))),
            h('div', {class: 'total'}, h('span', {}, 'Total'), h('span', {}, rupees(price.totalPaise)))));
}

function paymentCard(booking) {
    const payment = booking.payment;
    const reasons = {CUSTOMER: 'your cancellation', SHOW_CANCELLED: 'show cancelled', LATE_PAYMENT: 'late payment'};
    return h('section', {class: 'card stack'},
        h('h2', {}, 'Payment'),
        h('div', {class: 'lines'},
            h('div', {}, h('span', {}, `${payment.method.replace('_', ' ')} · ${payment.paidWith}`),
                h('span', {}, rupees(payment.amountPaise)))),
        payment.refunds.length > 0 && h('div', {class: 'stack'},
            h('h3', {}, 'Refunds'),
            payment.refunds.map(refund => h('div', {class: 'row'},
                h('span', {}, rupees(refund.amountPaise)),
                h('small', {}, reasons[refund.reason]),
                h('span', {class: 'spacer'}),
                statusBadge(refund.status)))));
}

function closedMessage(booking) {
    switch (booking.status) {
        case 'RELEASED': return 'You let these seats go.';
        case 'FAILED': return 'The payment was declined, so the seats were released. Pick seats again to retry.';
        case 'EXPIRED': return booking.payment
            ? 'Your payment arrived after the seats were released, so it has been refunded in full.'
            : 'The hold ran out before payment, so the seats were released.';
        case 'CANCELLED': return 'This booking is cancelled.';
        default: return booking.status;
    }
}

// ---- small helpers ----

function movieHeader(movie) {
    return h('div', {style: 'margin-bottom: 1rem'},
        h('h1', {}, movie.title),
        h('p', {class: 'muted'}, `${movie.certification} · ${duration(movie.durationMin)}`));
}

function statusBadge(status) {
    const kinds = {CONFIRMED: 'ok', COMPLETED: 'ok', HELD: 'accent', PAYMENT_PENDING: 'warn', INITIATED: 'warn',
                   CANCELLED: 'danger', FAILED: 'danger', EXPIRED: 'danger', RELEASED: ''};
    return badge(status.replace('_', ' '), kinds[status] ?? '');
}

function availabilityText(show) {
    switch (show.availability) {
        case 'SOLD_OUT': return 'Sold out';
        case 'FILLING_FAST': return `Filling fast · ${show.seatsLeft} left`;
        default: return `${show.seatsLeft} seats left`;
    }
}

function duration(minutes) {
    return `${Math.floor(minutes / 60)}h ${minutes % 60}m`;
}

function posterColour(title) {
    let hash = 0;
    for (const char of title) {
        hash = (hash * 31 + char.charCodeAt(0)) >>> 0;
    }
    const hue = hash % 360;
    return `linear-gradient(160deg, hsl(${hue} 70% 45%), hsl(${(hue + 40) % 360} 65% 25%))`;
}

// ---- routing ----

const routes = [
    [/^#?\/?$/, () => homePage()],
    [/^#\/movie\/(\d+)$/, ([id], params) => moviePage(id, params)],
    [/^#\/show\/(\d+)$/, ([id]) => seatsPage(id)],
    [/^#\/booking\/([\w-]+)$/, ([id]) => bookingPage(id)],
    [/^#\/bookings$/, (_, params) => historyPage(params)],
];

async function render() {
    timers.forEach(clearInterval);
    timers = [];
    const [path, query] = location.hash.split('?');
    const params = new URLSearchParams(query);
    for (const [pattern, page] of routes) {
        const match = path.match(pattern);
        if (match) {
            try {
                await page(match.slice(1), params);
            } catch (error) {
                showError(error);
                mount(app, empty(error instanceof ApiError && error.status === 404
                    ? 'Not found. It may belong to another customer.' : error.message));
            }
            return;
        }
    }
    mount(app, empty('Page not found'));
}

window.addEventListener('hashchange', render);
document.getElementById('api-url').textContent = baseUrl();
renderProfile();
await loadCities();
render();

