import {api, ApiError, baseUrl, rupees, showDateTime, showTime, storedIdentity, todayIst} from '../shared/api.js';
import {badge, confirmDialog, empty, formDialog, h, loading, mount, showError, toast, withBusy} from '../shared/ui.js';
import {seatMap} from '../shared/seatmap.js';

const admin = storedIdentity('moviebooking.admin', {role: 'ADMIN', name: 'Admin'});
const CITY_KEY = 'moviebooking.admin.cityId';
const THEATER_KEY = 'moviebooking.admin.theaterId';
const CATEGORIES = ['REGULAR', 'PREMIUM', 'RECLINER'];
const DAYS = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];
const CERTIFICATIONS = ['U', 'UA', 'A', 'S'];

const app = document.getElementById('app');
const call = (path, options) => api(path, admin, options);
const post = (path, body) => call(path, {method: 'POST', body});
const put = (path, body) => call(path, {method: 'PUT', body});

// money is entered in rupees and sent in paise
const toPaise = value => value === null ? null : Math.round(value * 100);
const toRupees = paise => paise === null || paise === undefined ? null : paise / 100;

// ---- shared pieces ----

function pageHead(title, ...actions) {
    return h('div', {class: 'page-head'}, h('h1', {}, title), actions);
}

function addButton(label, onclick) {
    return h('button', {class: 'primary', onclick}, `+ ${label}`);
}

function action(label, run, {danger = false, confirm} = {}) {
    const button = h('button', {class: `small ${danger ? 'danger' : ''}`}, label);
    button.addEventListener('click', async () => {
        if (confirm && !await confirmDialog(confirm, label, danger)) {
            return;
        }
        const done = await withBusy(button, run);
        if (done !== undefined) {
            render();
        }
    });
    return button;
}

function activeBadge(active) {
    return active ? badge('Active', 'ok') : badge('Inactive');
}

function table(headers, rows, emptyText) {
    if (!rows.length) {
        return empty(emptyText);
    }
    return h('div', {class: 'card table-wrap'}, h('table', {},
        h('thead', {}, h('tr', {}, headers.map(header =>
            h('th', {class: header.startsWith('#') ? 'num' : ''}, header.replace(/^#/, ''))))),
        h('tbody', {}, rows)));
}

async function cities() {
    return call('/api/v1/cities');
}

function selectedCity(list) {
    const saved = Number(localStorage.getItem(CITY_KEY));
    return list.find(city => city.id === saved) || list[0];
}

function citySelect(list, current) {
    return h('label', {}, h('span', {}, 'City'), h('select', {onchange: event => {
        localStorage.setItem(CITY_KEY, event.target.value);
        localStorage.removeItem(THEATER_KEY);
        render();
    }}, list.map(city => h('option', {value: city.id, selected: city.id === current?.id}, city.name))));
}

function theaterSelect(list, current) {
    return h('label', {}, h('span', {}, 'Theater'), h('select', {onchange: event => {
        localStorage.setItem(THEATER_KEY, event.target.value);
        render();
    }}, list.map(theater => h('option', {value: theater.id, selected: theater.id === current?.id},
                                  theater.active ? theater.name : `${theater.name} (inactive)`))));
}

function selectedTheater(list) {
    const saved = Number(localStorage.getItem(THEATER_KEY));
    return list.find(theater => theater.id === saved) || list[0];
}

/** "YYYY-MM-DDTHH:mm" for a datetime-local input, in this browser's time zone. */
function localInput(instant) {
    if (!instant) {
        return '';
    }
    const date = new Date(instant);
    return new Date(date.getTime() - date.getTimezoneOffset() * 60000).toISOString().slice(0, 16);
}

// ---- cities ----

async function citiesPage() {
    const list = await cities();
    const edit = city => formDialog(city ? 'Edit city' : 'New city', [
        {name: 'name', label: 'Name', required: true},
        {name: 'state', label: 'State'},
        {name: 'timezone', label: 'Time zone', placeholder: 'Asia/Kolkata',
         hint: 'Shows in this city are listed in this time zone.'},
    ], city || {}, values => city ? put(`/api/v1/admin/cities/${city.id}`, values)
                                  : post('/api/v1/admin/cities', values)).then(saved => saved && render());

    mount(app,
        pageHead('Cities', addButton('New city', () => edit())),
        table(['Name', 'State', 'Time zone', ''], list.map(city => h('tr', {},
            h('td', {}, h('b', {}, city.name)), h('td', {}, city.state || '–'), h('td', {}, city.timezone),
            h('td', {class: 'actions-cell'},
                action('Edit', () => edit(city).then(() => undefined)),
                action('Deactivate', () => post(`/api/v1/admin/cities/${city.id}/deactivate`),
                       {danger: true, confirm: `Deactivate ${city.name}? It disappears from the city picker.`}))))),
            'No cities yet. Add the first one.'),
        h('p', {class: 'muted', style: 'margin-top: .8rem'}, 'Only active cities are listed.'));
}

// ---- theaters and screens ----

async function theatersPage() {
    const cityList = await cities();
    if (!cityList.length) {
        mount(app, pageHead('Theaters & screens'), empty('Add a city first.'));
        return;
    }
    const city = selectedCity(cityList);
    const theaters = await call(`/api/v1/admin/theaters?cityId=${city.id}`);

    const edit = theater => formDialog(theater ? 'Edit theater' : `New theater in ${city.name}`, [
        {name: 'name', label: 'Name', required: true},
        {name: 'area', label: 'Area'},
        {name: 'address', label: 'Address'},
    ], theater || {}, values => theater
        ? put(`/api/v1/admin/theaters/${theater.id}`, values)
        : post('/api/v1/admin/theaters', {...values, cityId: city.id})).then(saved => saved && render());

    const editPrices = async theater => {
        const current = (await call(`/api/v1/admin/theaters/${theater.id}/prices`)).prices;
        await formDialog(`Seat prices at ${theater.name}`,
            CATEGORIES.map(category => ({name: category, label: `${category} (₹)`, type: 'number', min: 1, step: '0.01',
                                         required: true})),
            Object.fromEntries(CATEGORIES.map(category => [category, toRupees(current[category])])),
            values => put(`/api/v1/admin/theaters/${theater.id}/prices`,
                          {prices: Object.fromEntries(CATEGORIES.map(c => [c, toPaise(values[c])]))}));
    };

    const screenName = (title, initial, submit) =>
        formDialog(title, [{name: 'name', label: 'Screen name', required: true}], {name: initial},
                   values => submit(values.name)).then(saved => saved && render());

    mount(app,
        pageHead('Theaters & screens', addButton('New theater', () => edit())),
        h('div', {class: 'filters'}, citySelect(cityList, city)),
        theaters.length ? theaters.map(theater => h('section', {class: 'card'},
            h('div', {class: 'row'},
                h('div', {style: 'flex: 1'}, h('h2', {}, theater.name, ' ', activeBadge(theater.active)),
                    h('small', {}, [theater.area, theater.address].filter(Boolean).join(' · ') || 'No address')),
                action('Edit', () => edit(theater).then(() => undefined)),
                action('Seat prices', () => editPrices(theater).then(() => undefined)),
                theater.active && action('Deactivate', () => post(`/api/v1/admin/theaters/${theater.id}/deactivate`),
                    {danger: true, confirm: `Deactivate ${theater.name} and hide it from customers?`})),
            h('div', {class: 'screens'},
                theater.screens.map(screen => h('div', {class: 'screen-row'},
                    h('b', {}, screen.name), activeBadge(screen.active), h('span', {class: 'spacer'}),
                    h('a', {class: 'button small', href: `#/layouts?screen=${screen.id}&theater=${theater.id}`},
                      'Seat layouts'),
                    action('Rename', () => screenName('Rename screen', screen.name,
                        name => put(`/api/v1/admin/screens/${screen.id}`, {name})).then(() => undefined)),
                    screen.active && action('Deactivate', () => post(`/api/v1/admin/screens/${screen.id}/deactivate`),
                        {danger: true, confirm: `Deactivate ${screen.name}? No new shows can be scheduled on it.`}))),
                h('div', {}, action('+ Add screen', () => screenName('New screen', '',
                    name => post(`/api/v1/admin/theaters/${theater.id}/screens`, {name})).then(() => undefined))))))
            : empty(`No theaters in ${city.name} yet.`));
}

// ---- seat layouts ----

const LAYOUT_TEMPLATE = JSON.stringify({
    rows: [
        {label: 'A', segments: [{from: 1, to: 6, category: 'REGULAR'}, {aisle: 2}, {from: 7, to: 12, category: 'REGULAR'}]},
        {label: 'B', segments: [{from: 1, to: 6, category: 'REGULAR'}, {aisle: 2}, {from: 7, to: 12, category: 'REGULAR'}]},
        {label: 'C', segments: [{from: 1, to: 6, category: 'PREMIUM'}, {aisle: 2}, {from: 7, to: 12, category: 'PREMIUM'}]},
        {label: 'D', segments: [{aisle: 2}, {from: 1, to: 8, category: 'RECLINER'}]},
    ],
    blocked: ['A1'],
    wheelchair: ['D7', 'D8'],
}, null, 2);

async function layoutsPage(params) {
    const cityList = await cities();
    if (!cityList.length) {
        mount(app, pageHead('Seat layouts'), empty('Add a city, a theater and a screen first.'));
        return;
    }
    if (params.get('theater')) {
        localStorage.setItem(THEATER_KEY, params.get('theater'));
    }
    const city = selectedCity(cityList);
    const theaters = await call(`/api/v1/admin/theaters?cityId=${city.id}`);
    const theater = selectedTheater(theaters);
    const screens = theater?.screens || [];
    const screen = screens.find(s => String(s.id) === params.get('screen')) || screens[0];

    const filters = h('div', {class: 'filters'}, citySelect(cityList, city),
        theaters.length > 0 && theaterSelect(theaters, theater),
        screens.length > 0 && h('label', {}, h('span', {}, 'Screen'), h('select', {onchange: event =>
            location.hash = `#/layouts?screen=${event.target.value}&theater=${theater.id}`},
            screens.map(s => h('option', {value: s.id, selected: s.id === screen.id}, s.name)))));
    if (!screen) {
        mount(app, pageHead('Seat layouts'), filters, empty('This theater has no screens yet.'));
        return;
    }
    const layouts = await call(`/api/v1/admin/screens/${screen.id}/layouts`);

    const editJson = (title, save) => formDialog(title, [
        {name: 'json', label: 'Layout', type: 'textarea', rows: 18, required: true,
         hint: 'Rows of segments: a run of seats {from, to, category} or an {aisle: width} gap. '
               + 'Categories: REGULAR, PREMIUM, RECLINER. "blocked" seats are never sold.'},
    ], {json: LAYOUT_TEMPLATE}, values => save(JSON.parse(values.json))).then(saved => saved && render());

    mount(app,
        pageHead(`Seat layouts · ${screen.name}`,
            addButton('New draft', () => editJson('New layout draft',
                body => post(`/api/v1/admin/screens/${screen.id}/layouts`, body)))),
        filters,
        layouts.length ? layouts.map(layout => h('section', {class: 'card stack'},
            h('div', {class: 'row'},
                h('h2', {style: 'flex: 1; margin: 0'}, `Version ${layout.version} `,
                    badge(layout.status, {ACTIVE: 'ok', DRAFT: 'accent'}[layout.status] || '')),
                h('small', {}, `${layout.totalSeats} seats · ${layout.gridRows} × ${layout.gridCols}`),
                layout.status === 'DRAFT' && action('Replace draft', () => editJson(`Edit draft v${layout.version}`,
                    body => put(`/api/v1/admin/layouts/${layout.id}`, body)).then(() => undefined)),
                layout.status === 'DRAFT' && action('Activate', () => post(`/api/v1/admin/layouts/${layout.id}/activate`),
                    {confirm: 'Activate this layout? New shows on the screen will use it; existing shows keep theirs.'})),
            seatMap({...layout, seats: layout.seats.map(seat =>
                ({...seat, status: seat.type === 'BLOCKED' ? 'BLOCKED' : 'AVAILABLE'}))})))
            : empty('No layouts yet. Draft one to describe the screen\'s seats.'));
}

// ---- movies ----

async function moviesPage() {
    const movies = await call('/api/v1/admin/movies');
    const edit = movie => formDialog(movie ? 'Edit movie' : 'New movie', [
        {name: 'title', label: 'Title', required: true},
        {name: 'durationMin', label: 'Duration (minutes)', type: 'number', min: 1, required: true,
         hint: 'A show takes the screen this long, plus a 20-minute cleaning buffer.'},
        {name: 'certification', label: 'Certification', type: 'select', options: CERTIFICATIONS.map(c => [c, c])},
        {name: 'releaseDate', label: 'Release date', type: 'date'},
    ], movie || {certification: 'UA'}, values => movie ? put(`/api/v1/admin/movies/${movie.id}`, values)
                                                       : post('/api/v1/admin/movies', values))
        .then(saved => saved && render());

    mount(app,
        pageHead('Movies', addButton('New movie', () => edit())),
        table(['Title', 'Duration', 'Certification', 'Release', 'Status', ''], movies.map(movie =>
            h('tr', {class: movie.active ? '' : 'inactive'},
                h('td', {}, h('b', {}, movie.title)), h('td', {}, `${movie.durationMin} min`),
                h('td', {}, movie.certification), h('td', {}, movie.releaseDate || '–'),
                h('td', {}, activeBadge(movie.active)),
                h('td', {class: 'actions-cell'},
                    action('Edit', () => edit(movie).then(() => undefined)),
                    movie.active && action('Deactivate', () => post(`/api/v1/admin/movies/${movie.id}/deactivate`),
                        {danger: true, confirm: `Deactivate ${movie.title}? No new shows can be scheduled.`}))))),
            'No movies yet.'));
}

// ---- shows ----

async function showsPage(params) {
    const cityList = await cities();
    if (!cityList.length) {
        mount(app, pageHead('Shows'), empty('Add a city and a theater first.'));
        return;
    }
    const city = selectedCity(cityList);
    const theaters = await call(`/api/v1/admin/theaters?cityId=${city.id}`);
    const theater = selectedTheater(theaters);
    const date = params.get('date') || todayIst();
    const filters = h('div', {class: 'filters'}, citySelect(cityList, city),
        theaters.length > 0 && theaterSelect(theaters, theater),
        h('label', {}, h('span', {}, 'Date'), h('input', {type: 'date', value: date,
            onchange: event => location.hash = `#/shows?date=${event.target.value}`})));
    if (!theater) {
        mount(app, pageHead('Shows'), filters, empty(`No theaters in ${city.name} yet.`));
        return;
    }
    const [shows, movies, policies] = await Promise.all([
        call(`/api/v1/admin/shows?theaterId=${theater.id}&date=${date}`),
        call('/api/v1/admin/movies'),
        call('/api/v1/admin/refund-policies')]);
    const movieTitle = new Map(movies.map(movie => [movie.id, movie.title]));
    const screenName = new Map(theater.screens.map(screen => [screen.id, screen.name]));
    const policyName = new Map(policies.map(policy => [policy.id, policy.name]));

    const schedule = () => formDialog(`Schedule a show at ${theater.name}`, [
        {name: 'movieId', label: 'Movie', type: 'select', required: true,
         options: movies.filter(movie => movie.active).map(movie => [movie.id, `${movie.title} (${movie.durationMin} min)`])},
        {name: 'screenId', label: 'Screen', type: 'select', required: true,
         options: theater.screens.filter(screen => screen.active).map(screen => [screen.id, screen.name])},
        {name: 'start', label: 'Starts (IST)', type: 'datetime-local', required: true},
        {name: 'language', label: 'Language', placeholder: 'HI', required: true},
        {name: 'format', label: 'Format', placeholder: '2D', required: true},
        ...CATEGORIES.map(category => ({name: `price${category}`, label: `${category} price (₹, optional)`,
                                        type: 'number', step: '0.01', min: 1,
                                        hint: category === 'REGULAR' ? 'Leave empty to use the theater\'s prices.' : null})),
        {name: 'refundPolicyId', label: 'Refund policy', type: 'select',
         options: [['', 'The default policy'], ...policies.map(policy => [policy.id, policy.name])]},
    ], {start: `${date}T18:00`, language: 'HI', format: '2D'}, values => {
        const priceOverrides = Object.fromEntries(CATEGORIES
            .filter(category => values[`price${category}`] !== null)
            .map(category => [category, toPaise(values[`price${category}`])]));
        return post('/api/v1/admin/shows', {
            movieId: Number(values.movieId), screenId: Number(values.screenId),
            startTime: `${values.start}:00+05:30`, language: values.language, format: values.format,
            priceOverrides, refundPolicyId: values.refundPolicyId ? Number(values.refundPolicyId) : null});
    }).then(saved => {
        if (saved) {
            toast(`Scheduled. Open it for sale when you're ready.`, 'ok');
            location.hash = `#/shows?date=${saved.showDate}`;
            render();
        }
    });

    const prices = show => formDialog('Prices for this show', CATEGORIES.map(category =>
        ({name: category, label: `${category} (₹)`, type: 'number', step: '0.01', min: 1,
          hint: category === 'REGULAR' ? 'Only the categories you fill in change. Existing holds keep their price.' : null})),
        {}, values => {
            const changed = Object.fromEntries(CATEGORIES.filter(c => values[c] !== null)
                .map(c => [c, toPaise(values[c])]));
            return put(`/api/v1/admin/shows/${show.id}/prices`, {prices: changed});
        });

    const statusKind = {OPEN: 'ok', SCHEDULED: 'accent', CANCELLED: 'danger'};
    mount(app,
        pageHead('Shows', addButton('Schedule show', schedule)),
        filters,
        table(['Time', 'Movie', 'Screen', 'Language', 'Status', '#Seats', '#From', 'Refunds', ''], shows.map(show =>
            h('tr', {class: show.status === 'CANCELLED' ? 'inactive' : ''},
                h('td', {}, h('b', {}, showTime(show.startTime)), h('br'),
                    h('small', {}, `until ${showTime(show.endTime)}`)),
                h('td', {}, movieTitle.get(show.movieId) || `#${show.movieId}`),
                h('td', {}, screenName.get(show.screenId) || `#${show.screenId}`),
                h('td', {}, `${show.language} · ${show.format}`),
                h('td', {}, badge(show.status, statusKind[show.status])),
                h('td', {class: 'num'}, show.totalSeats),
                h('td', {class: 'num'}, rupees(show.priceFromPaise)),
                h('td', {}, show.refundPolicyId ? policyName.get(show.refundPolicyId) : h('small', {}, 'default')),
                h('td', {class: 'actions-cell'}, show.status !== 'CANCELLED' && [
                    show.status === 'SCHEDULED' && action('Open for sale', () => post(`/api/v1/admin/shows/${show.id}/open`)),
                    action('Prices', () => prices(show).then(saved => saved ? saved : undefined)),
                    action('Seats', () => seatsDialog(show).then(() => undefined)),
                    action('Cancel', () => post(`/api/v1/admin/shows/${show.id}/cancel`).then(result => {
                        toast('Show cancelled. Holds are released and every booking refunded in full.', 'ok');
                        return result;
                    }), {danger: true, confirm: 'Cancel this show? Every customer is refunded in full, fees included.'}),
                ])))),
            `No shows at ${theater.name} on ${date}.`));
}

/** The show's live seat map; select seats to block or unblock them for this show only. */
function seatsDialog(show) {
    return new Promise(resolve => {
        const selected = new Set();
        const body = h('div', {}, loading());
        const dialog = h('dialog', {class: 'dialog seats'},
            h('h2', {}, `Seats · ${showDateTime(show.startTime)}`),
            h('p', {class: 'muted'}, 'Select free or blocked seats, then block or unblock them for this show. '
                + 'Held and booked seats can\'t be changed here.'),
            body);
        const load = async () => {
            const map = await call(`/api/v1/shows/${show.id}/seats`);
            const categories = new Map(map.categories.map(c => [c.id, c.code]));
            const seats = map.seats.map(seat => ({...seat, id: seat.seatId, category: categories.get(seat.categoryId)}));
            const change = (verb, path) => {
                const button = h('button', {disabled: !selected.size}, `${verb} ${selected.size || ''}`);
                button.addEventListener('click', () => withBusy(button, async () => {
                    const result = await post(`/api/v1/admin/shows/${show.id}/seats/${path}`, {seatIds: [...selected]});
                    const skipped = result.unchangedSeatIds.length;
                    toast(skipped ? `${selected.size - skipped} changed, ${skipped} left as they were`
                                  : `${verb}ed ${selected.size} seat${selected.size === 1 ? '' : 's'}`, 'ok');
                    selected.clear();
                    await load();
                }));
                return button;
            };
            mount(body,
                seatMap({...map, seats}, {
                    selected,
                    canSelect: seat => seat.status === 'AVAILABLE' || seat.status === 'BLOCKED',
                    onToggle: seat => {
                        selected.has(seat.id) ? selected.delete(seat.id) : selected.add(seat.id);
                        load();
                    },
                }),
                h('div', {class: 'actions'},
                    h('button', {class: 'ghost', onclick: () => dialog.close()}, 'Close'),
                    change('Unblock', 'unblock'), change('Block', 'block')));
        };
        dialog.addEventListener('close', () => {
            dialog.remove();
            resolve();
        });
        document.body.append(dialog);
        dialog.showModal();
        load().catch(showError);
    });
}

// ---- pricing rules ----

async function pricingPage() {
    const [rules, cityList] = await Promise.all([call('/api/v1/admin/pricing-rules'), cities()]);
    const city = cityList.length ? selectedCity(cityList) : null;
    const theaters = city ? await call(`/api/v1/admin/theaters?cityId=${city.id}`) : [];
    const cityName = new Map(cityList.map(c => [c.id, c.name]));
    const theaterName = new Map(theaters.map(t => [t.id, t.name]));

    const scopeOptions = [['GLOBAL:', 'Everywhere'],
        ...cityList.map(c => [`CITY:${c.id}`, `City · ${c.name}`]),
        ...theaters.map(t => [`THEATER:${t.id}`, `Theater · ${t.name}`])];
    const describeScope = rule => rule.scopeType === 'GLOBAL' ? 'Everywhere'
        : rule.scopeType === 'CITY' ? `City · ${cityName.get(rule.scopeId) || '#' + rule.scopeId}`
        : `Theater · ${theaterName.get(rule.scopeId) || '#' + rule.scopeId}`;

    const toBody = values => {
        const [scopeType, scopeId] = values.scope.split(':');
        const days = values.days.split(/[\s,]+/).filter(Boolean).map(day => {
            const index = DAYS.findIndex(name => name.toLowerCase() === day.slice(0, 3).toLowerCase());
            if (index < 0) {
                throw new ApiError(400, {detail: `"${day}" isn't a day; use Mon … Sun`});
            }
            return index + 1;
        });
        return {name: values.name, scopeType, scopeId: scopeId ? Number(scopeId) : null, daysOfWeek: days,
                adjustmentType: values.adjustmentType,
                adjustmentValue: values.adjustmentType === 'FLAT' ? toPaise(values.value) : values.value,
                validFrom: values.validFrom, validTo: values.validTo, active: values.active};
    };
    const edit = rule => formDialog(rule ? 'Edit pricing rule' : 'New pricing rule', [
        {name: 'name', label: 'Name', required: true},
        {name: 'scope', label: 'Applies to', type: 'select', options: scopeOptions,
         hint: `When several rules match, the most specific wins (theater, then city). Theaters listed are in ${city?.name ?? 'the selected city'}.`},
        {name: 'days', label: 'Days', required: true, placeholder: 'Sat, Sun'},
        {name: 'adjustmentType', label: 'Surcharge', type: 'select',
         options: [['PERCENT', 'Percent of the seat price'], ['FLAT', 'Flat amount per seat (₹)']]},
        {name: 'value', label: 'Value', type: 'number', min: 0.01, step: '0.01', required: true},
        {name: 'validFrom', label: 'From (optional)', type: 'date'},
        {name: 'validTo', label: 'Until (optional)', type: 'date'},
        {name: 'active', label: 'Active', type: 'checkbox'},
    ], rule ? {...rule, scope: `${rule.scopeType}:${rule.scopeId ?? ''}`,
               days: rule.daysOfWeek.map(day => DAYS[day - 1]).join(', '),
               value: rule.adjustmentType === 'FLAT' ? toRupees(rule.adjustmentValue) : rule.adjustmentValue}
            : {scope: 'GLOBAL:', adjustmentType: 'PERCENT', active: true},
    values => rule ? put(`/api/v1/admin/pricing-rules/${rule.id}`, toBody(values))
                   : post('/api/v1/admin/pricing-rules', toBody(values))).then(saved => saved && render());

    mount(app,
        pageHead('Pricing rules', addButton('New rule', () => edit())),
        h('p', {class: 'muted'}, 'Day-of-week surcharges on top of each show\'s seat prices.'),
        table(['Name', 'Applies to', 'Days', 'Surcharge', 'Dates', 'Status', ''], rules.map(rule =>
            h('tr', {class: rule.active ? '' : 'inactive'},
                h('td', {}, h('b', {}, rule.name)), h('td', {}, describeScope(rule)),
                h('td', {}, rule.daysOfWeek.map(day => DAYS[day - 1]).join(', ')),
                h('td', {}, rule.adjustmentType === 'PERCENT' ? `+${rule.adjustmentValue}%`
                                                              : `+${rupees(rule.adjustmentValue)} a seat`),
                h('td', {}, rule.validFrom || rule.validTo ? `${rule.validFrom || '…'} → ${rule.validTo || '…'}` : 'Always'),
                h('td', {}, rule.active ? badge('Active', 'ok') : badge('Paused')),
                h('td', {class: 'actions-cell'},
                    action('Edit', () => edit(rule).then(() => undefined)),
                    action(rule.active ? 'Pause' : 'Resume', () => put(`/api/v1/admin/pricing-rules/${rule.id}`,
                        {...rule, active: !rule.active})),
                    action('Delete', () => call(`/api/v1/admin/pricing-rules/${rule.id}`, {method: 'DELETE'}),
                        {danger: true, confirm: `Delete "${rule.name}"? Existing holds keep their prices.`}))))),
            'No pricing rules.'));
}

// ---- coupons ----

async function couponsPage() {
    const coupons = await call('/api/v1/admin/coupons');
    const toBody = (values, withCode) => ({
        ...(withCode ? {code: values.code} : {}),
        discountType: values.discountType,
        discountValue: values.discountType === 'FLAT' ? toPaise(values.value) : values.value,
        maxDiscountPaise: toPaise(values.maxDiscount),
        minOrderPaise: toPaise(values.minOrder) ?? 0,
        validFrom: new Date(values.validFrom).toISOString(),
        validTo: new Date(values.validTo).toISOString(),
        maxUses: values.maxUses, perUserLimit: values.perUserLimit ?? 1,
        scopes: (values.scopes || '').split(/[\s,]+/).filter(Boolean).map(scope => {
            const [scopeType, scopeId] = scope.split(':');
            return {scopeType: scopeType.toUpperCase(), scopeId: Number(scopeId)};
        }),
    });
    const edit = coupon => formDialog(coupon ? `Edit ${coupon.code}` : 'New coupon', [
        ...(coupon ? [] : [{name: 'code', label: 'Code', required: true, placeholder: 'FIRST50',
                             hint: '3–30 letters and digits. It can\'t be changed later.'}]),
        {name: 'discountType', label: 'Discount', type: 'select',
         options: [['FLAT', 'Flat amount (₹)'], ['PERCENT', 'Percent of the order']]},
        {name: 'value', label: 'Value', type: 'number', min: 0.01, step: '0.01', required: true},
        {name: 'maxDiscount', label: 'Maximum discount (₹, percent only)', type: 'number', step: '0.01'},
        {name: 'minOrder', label: 'Minimum order (₹)', type: 'number', step: '0.01', min: 0},
        {name: 'validFrom', label: 'Valid from', type: 'datetime-local', required: true},
        {name: 'validTo', label: 'Valid until', type: 'datetime-local', required: true},
        {name: 'maxUses', label: 'Total uses (empty = unlimited)', type: 'number', min: 1},
        {name: 'perUserLimit', label: 'Uses per customer', type: 'number', min: 1},
        {name: 'scopes', label: 'Only for (optional)', placeholder: 'CITY:1, MOVIE:3',
         hint: 'CITY, THEATER, MOVIE or CATEGORY with its id. Empty means everywhere.'},
    ], coupon ? {...coupon, value: coupon.discountType === 'FLAT' ? toRupees(coupon.discountValue) : coupon.discountValue,
                 maxDiscount: toRupees(coupon.maxDiscountPaise), minOrder: toRupees(coupon.minOrderPaise),
                 validFrom: localInput(coupon.validFrom), validTo: localInput(coupon.validTo),
                 scopes: coupon.scopes.map(s => `${s.scopeType}:${s.scopeId}`).join(', ')}
              : {discountType: 'FLAT', perUserLimit: 1, validFrom: localInput(new Date()),
                 validTo: localInput(new Date(Date.now() + 30 * 86400000))},
    values => coupon ? put(`/api/v1/admin/coupons/${coupon.id}`, toBody(values, false))
                     : post('/api/v1/admin/coupons', toBody(values, true))).then(saved => saved && render());

    mount(app,
        pageHead('Coupons', addButton('New coupon', () => edit())),
        table(['Code', 'Discount', 'Min order', 'Valid', 'Used', 'Per customer', 'Where', 'Status', ''],
            coupons.map(coupon => h('tr', {class: coupon.active ? '' : 'inactive'},
                h('td', {}, h('b', {}, coupon.code)),
                h('td', {}, coupon.discountType === 'FLAT' ? rupees(coupon.discountValue)
                    : `${coupon.discountValue}%${coupon.maxDiscountPaise ? ` up to ${rupees(coupon.maxDiscountPaise)}` : ''}`),
                h('td', {}, coupon.minOrderPaise ? rupees(coupon.minOrderPaise) : '–'),
                h('td', {}, h('small', {}, `${showDateTime(coupon.validFrom)} → ${showDateTime(coupon.validTo)}`)),
                h('td', {}, coupon.maxUses
                    ? h('div', {class: 'row'}, h('div', {class: 'meter'},
                        h('span', {style: `width: ${Math.min(100, 100 * coupon.usedCount / coupon.maxUses)}%`})),
                        `${coupon.usedCount}/${coupon.maxUses}`)
                    : `${coupon.usedCount}`),
                h('td', {class: 'num'}, coupon.perUserLimit),
                h('td', {}, coupon.scopes.length ? coupon.scopes.map(s => `${s.scopeType} ${s.scopeId}`).join(', ')
                                                 : 'Everywhere'),
                h('td', {}, activeBadge(coupon.active)),
                h('td', {class: 'actions-cell'}, coupon.active && [
                    action('Edit', () => edit(coupon).then(() => undefined)),
                    action('Deactivate', () => post(`/api/v1/admin/coupons/${coupon.id}/deactivate`),
                        {danger: true, confirm: `Deactivate ${coupon.code}? No new holds can use it.`})]))),
            'No coupons yet.'));
}

// ---- refund policies ----

async function refundsPage() {
    const policies = await call('/api/v1/admin/refund-policies');
    const toBody = values => ({
        name: values.name, type: values.type, refundFees: values.type === 'SLAB' && values.refundFees,
        slabs: values.type !== 'SLAB' ? [] : [...(values.slabs || '').matchAll(/(\d+)\s*h?\s*[:=→-]\s*(\d+)\s*%?/g)]
            .map(([, hours, percent]) => ({minHoursBefore: Number(hours), percent: Number(percent)})),
    });
    const edit = policy => formDialog(policy ? `Edit ${policy.name}` : 'New refund policy', [
        {name: 'name', label: 'Name', required: true},
        {name: 'type', label: 'Type', type: 'select', options: [['SLAB', 'By time before the show'],
            ['FULL', 'Always a full refund'], ['NON_REFUNDABLE', 'Non-refundable']]},
        {name: 'slabs', label: 'Slabs (SLAB only)', placeholder: '24:100, 4:50',
         hint: 'hours before the show : percent refunded. Less time than the smallest slab refunds nothing.'},
        {name: 'refundFees', label: 'Also refund the convenience fee (SLAB only)', type: 'checkbox'},
    ], policy ? {...policy, slabs: policy.slabs.map(s => `${s.minHoursBefore}:${s.percent}`).join(', ')}
              : {type: 'SLAB', slabs: '24:100, 4:50'},
    values => policy ? put(`/api/v1/admin/refund-policies/${policy.id}`, toBody(values))
                     : post('/api/v1/admin/refund-policies', toBody(values))).then(saved => saved && render());

    const describe = policy => ({
        FULL: 'Everything back, fees included, whenever the customer cancels.',
        NON_REFUNDABLE: 'Customers can cancel to free the seats, but get nothing back.',
        SLAB: `A share of the ticket price by how early they cancel${policy.refundFees ? ', plus the fee' : '; fees kept'}.`,
    })[policy.type];

    mount(app,
        pageHead('Refund policies', addButton('New policy', () => edit())),
        h('p', {class: 'muted'}, 'Each booking keeps a copy of the policy it was sold under, so editing a policy only '
            + 'affects bookings confirmed afterwards. Shows without their own policy use the default.'),
        h('div', {class: 'grid-2'}, policies.map(policy => h('section', {class: 'card stack'},
            h('div', {class: 'row'}, h('h2', {style: 'flex: 1; margin: 0'}, policy.name),
                policy.isDefault && badge('Default', 'accent')),
            h('p', {class: 'muted'}, describe(policy)),
            policy.slabs.length > 0 && h('div', {class: 'slabs'}, policy.slabs.map(slab =>
                badge(`${slab.minHoursBefore}h+ → ${slab.percent}%`, slab.percent ? 'ok' : ''))),
            h('div', {class: 'row'},
                action('Edit', () => edit(policy).then(() => undefined)),
                !policy.isDefault && action('Make default', () =>
                    post(`/api/v1/admin/refund-policies/${policy.id}/make-default`)))))));
}

// ---- routing ----

const routes = {
    cities: citiesPage,
    theaters: theatersPage,
    layouts: layoutsPage,
    movies: moviesPage,
    shows: showsPage,
    pricing: pricingPage,
    coupons: couponsPage,
    refunds: refundsPage,
};

async function render() {
    const [path, query] = location.hash.replace(/^#\/?/, '').split('?');
    const name = routes[path] ? path : 'cities';
    for (const link of document.querySelectorAll('#nav a')) {
        link.classList.toggle('current', link.getAttribute('href') === `#/${name}`);
    }
    if (!app.firstChild) {
        mount(app, loading());
    }
    try {
        await routes[name](new URLSearchParams(query));
    } catch (error) {
        showError(error);
        mount(app, empty(error.message));
    }
}

window.addEventListener('hashchange', render);
document.getElementById('api-url').textContent = baseUrl();
render();

