import {api, ApiError, baseUrl, rupees, showDateTime, showTime, storedIdentity, todayIst} from '../shared/api.js';
import {badge, confirmDialog, empty, formDialog, h, loading, mount, showError, toast, withBusy} from '../shared/ui.js';
import {seatMap} from '../shared/seatmap.js';

const admin = storedIdentity('moviebooking.admin', {role: 'ADMIN', name: 'Admin'});
const CITY_KEY = 'moviebooking.admin.cityId';
const THEATER_KEY = 'moviebooking.admin.theaterId';
const CATEGORIES = ['REGULAR', 'PREMIUM', 'RECLINER'];
const DAYS = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];
const CERTIFICATIONS = ['U', 'UA', 'A', 'S'];

const app = document.getElementById('app');
const call = (path, options) => api(path, admin, options);
const post = (path, body) => call(path, {method: 'POST', body});
const put = (path, body) => call(path, {method: 'PUT', body});

// money is entered in rupees and sent in paise
const toPaise = value => value === null ? null : Math.round(value * 100);
const toRupees = paise => paise === null || paise === undefined ? null : paise / 100;

// ---- shared pieces ----

function pageHead(title, ...actions) {
    return h('div', {class: 'page-head'}, h('h1', {}, title), actions);
}

function addButton(label, onclick) {
    return h('button', {class: 'primary', onclick}, `+ ${label}`);
}

function action(label, run, {danger = false, confirm} = {}) {
    const button = h('button', {class: `small ${danger ? 'danger' : ''}`}, label);
    button.addEventListener('click', async () => {
        if (confirm && !await confirmDialog(confirm, label, danger)) {
            return;
        }
        const done = await withBusy(button, run);
        if (done !== undefined) {
            render();
        }
    });
    return button;
}

function activeBadge(active) {
    return active ? badge('Active', 'ok') : badge('Inactive');
}

function table(headers, rows, emptyText) {
    if (!rows.length) {
        return empty(emptyText);
    }
    return h('div', {class: 'card table-wrap'}, h('table', {},
        h('thead', {}, h('tr', {}, headers.map(header =>
            h('th', {class: header.startsWith('#') ? 'num' : ''}, header.replace(/^#/, ''))))),
        h('tbody', {}, rows)));
}

async function cities() {
    return call('/api/v1/cities');
}

function selectedCity(list) {
    const saved = Number(localStorage.getItem(CITY_KEY));
    return list.find(city => city.id === saved) || list[0];
}

function citySelect(list, current) {
    return h('label', {}, h('span', {}, 'City'), h('select', {onchange: event => {
        localStorage.setItem(CITY_KEY, event.target.value);
        localStorage.removeItem(THEATER_KEY);
        render();
    }}, list.map(city => h('option', {value: city.id, selected: city.id === current?.id}, city.name))));
}

function theaterSelect(list, current) {
    return h('label', {}, h('span', {}, 'Theater'), h('select', {onchange: event => {
        localStorage.setItem(THEATER_KEY, event.target.value);
        render();
    }}, list.map(theater => h('option', {value: theater.id, selected: theater.id === current?.id},
                                  theater.active ? theater.name : `${theater.name} (inactive)`))));
}

function selectedTheater(list) {
    const saved = Number(localStorage.getItem(THEATER_KEY));
    return list.find(theater => theater.id === saved) || list[0];
}

/** "YYYY-MM-DDTHH:mm" for a datetime-local input, in this browser's time zone. */
function localInput(instant) {
    if (!instant) {
        return '';
    }
    const date = new Date(instant);
    return new Date(date.getTime() - date.getTimezoneOffset() * 60000).toISOString().slice(0, 16);
}

