/** The show's live seat map; select seats to block or unblock them for this show only. */
function seatsDialog(show) {
    return new Promise(resolve => {
        const selected = new Set();
        const body = h('div', {}, loading());
        const dialog = h('dialog', {class: 'dialog seats'},
            h('h2', {}, `Seats · ${showDateTime(show.startTime)}`),
            h('p', {class: 'muted'}, 'Select free or blocked seats, then block or unblock them for this show. '
                + 'Held and booked seats can\'t be changed here.'),
            body);
        const load = async () => {
            const map = await call(`/api/v1/shows/${show.id}/seats`);
            const categories = new Map(map.categories.map(c => [c.id, c.code]));
            const seats = map.seats.map(seat => ({...seat, id: seat.seatId, category: categories.get(seat.categoryId)}));
            const change = (verb, path) => {
                const button = h('button', {disabled: !selected.size}, `${verb} ${selected.size || ''}`);
                button.addEventListener('click', () => withBusy(button, async () => {
                    const result = await post(`/api/v1/admin/shows/${show.id}/seats/${path}`, {seatIds: [...selected]});
                    const skipped = result.unchangedSeatIds.length;
                    toast(skipped ? `${selected.size - skipped} changed, ${skipped} left as they were`
                                  : `${verb}ed ${selected.size} seat${selected.size === 1 ? '' : 's'}`, 'ok');
                    selected.clear();
                    await load();
                }));
                return button;
            };
            mount(body,
                seatMap({...map, seats}, {
                    selected,
                    canSelect: seat => seat.status === 'AVAILABLE' || seat.status === 'BLOCKED',
                    onToggle: seat => {
                        selected.has(seat.id) ? selected.delete(seat.id) : selected.add(seat.id);
                        load();
                    },
                }),
                h('div', {class: 'actions'},
                    h('button', {class: 'ghost', onclick: () => dialog.close()}, 'Close'),
                    change('Unblock', 'unblock'), change('Block', 'block')));
        };
        dialog.addEventListener('close', () => {
            dialog.remove();
            resolve();
        });
        document.body.append(dialog);
        dialog.showModal();
        load().catch(showError);
    });
}

// ---- pricing rules ----

async function pricingPage() {
    const [rules, cityList] = await Promise.all([call('/api/v1/admin/pricing-rules'), cities()]);
    const city = cityList.length ? selectedCity(cityList) : null;
    const theaters = city ? await call(`/api/v1/admin/theaters?cityId=${city.id}`) : [];
    const cityName = new Map(cityList.map(c => [c.id, c.name]));
    const theaterName = new Map(theaters.map(t => [t.id, t.name]));

    const scopeOptions = [['GLOBAL:', 'Everywhere'],
        ...cityList.map(c => [`CITY:${c.id}`, `City · ${c.name}`]),
        ...theaters.map(t => [`THEATER:${t.id}`, `Theater · ${t.name}`])];
    const describeScope = rule => rule.scopeType === 'GLOBAL' ? 'Everywhere'
        : rule.scopeType === 'CITY' ? `City · ${cityName.get(rule.scopeId) || '#' + rule.scopeId}`
        : `Theater · ${theaterName.get(rule.scopeId) || '#' + rule.scopeId}`;

    const toBody = values => {
        const [scopeType, scopeId] = values.scope.split(':');
        const days = values.days.split(/[\s,]+/).filter(Boolean).map(day => {
            const index = DAYS.findIndex(name => name.toLowerCase() === day.slice(0, 3).toLowerCase());
            if (index < 0) {
                throw new ApiError(400, {detail: `"${day}" isn't a day; use Mon … Sun`});
            }
            return index + 1;
        });
        return {name: values.name, scopeType, scopeId: scopeId ? Number(scopeId) : null, daysOfWeek: days,
                adjustmentType: values.adjustmentType,
                adjustmentValue: values.adjustmentType === 'FLAT' ? toPaise(values.value) : values.value,
                validFrom: values.validFrom, validTo: values.validTo, active: values.active};
    };
    const edit = rule => formDialog(rule ? 'Edit pricing rule' : 'New pricing rule', [
        {name: 'name', label: 'Name', required: true},
        {name: 'scope', label: 'Applies to', type: 'select', options: scopeOptions,
         hint: `When several rules match, the most specific wins (theater, then city). Theaters listed are in ${city?.name ?? 'the selected city'}.`},
        {name: 'days', label: 'Days', required: true, placeholder: 'Sat, Sun'},
        {name: 'adjustmentType', label: 'Surcharge', type: 'select',
         options: [['PERCENT', 'Percent of the seat price'], ['FLAT', 'Flat amount per seat (₹)']]},
        {name: 'value', label: 'Value', type: 'number', min: 0.01, step: '0.01', required: true},
        {name: 'validFrom', label: 'From (optional)', type: 'date'},
        {name: 'validTo', label: 'Until (optional)', type: 'date'},
        {name: 'active', label: 'Active', type: 'checkbox'},
    ], rule ? {...rule, scope: `${rule.scopeType}:${rule.scopeId ?? ''}`,
               days: rule.daysOfWeek.map(day => DAYS[day - 1]).join(', '),
               value: rule.adjustmentType === 'FLAT' ? toRupees(rule.adjustmentValue) : rule.adjustmentValue}
            : {scope: 'GLOBAL:', adjustmentType: 'PERCENT', active: true},
    values => rule ? put(`/api/v1/admin/pricing-rules/${rule.id}`, toBody(values))
                   : post('/api/v1/admin/pricing-rules', toBody(values))).then(saved => saved && render());

    mount(app,
        pageHead('Pricing rules', addButton('New rule', () => edit())),
        h('p', {class: 'muted'}, 'Day-of-week surcharges on top of each show\'s seat prices.'),
        table(['Name', 'Applies to', 'Days', 'Surcharge', 'Dates', 'Status', ''], rules.map(rule =>
            h('tr', {class: rule.active ? '' : 'inactive'},
                h('td', {}, h('b', {}, rule.name)), h('td', {}, describeScope(rule)),
                h('td', {}, rule.daysOfWeek.map(day => DAYS[day - 1]).join(', ')),
                h('td', {}, rule.adjustmentType === 'PERCENT' ? `+${rule.adjustmentValue}%`
                                                              : `+${rupees(rule.adjustmentValue)} a seat`),
                h('td', {}, rule.validFrom || rule.validTo ? `${rule.validFrom || '…'} → ${rule.validTo || '…'}` : 'Always'),
                h('td', {}, rule.active ? badge('Active', 'ok') : badge('Paused')),
                h('td', {class: 'actions-cell'},
                    action('Edit', () => edit(rule).then(() => undefined)),
                    action(rule.active ? 'Pause' : 'Resume', () => put(`/api/v1/admin/pricing-rules/${rule.id}`,
                        {...rule, active: !rule.active})),
                    action('Delete', () => call(`/api/v1/admin/pricing-rules/${rule.id}`, {method: 'DELETE'}),
                        {danger: true, confirm: `Delete "${rule.name}"? Existing holds keep their prices.`}))))),
            'No pricing rules.'));
}

