S='src/main/java/com/sumit/movieticketbookingsystem/'
modules = {
    "catalog":      ("Cities, theaters, screens, seat layouts and movies.", ["shared"]),
    "inventory":    ("The seats of each show and who holds or owns them.", ["catalog", "shared"]),
    "pricing":      ("Seat prices, day-of-week rules and coupons.", ["catalog", "shared"]),
    "show":         ("Shows: scheduling, the browse pages and the seat map.", ["catalog", "inventory", "pricing", "shared"]),
    "payment":      ("Taking payments and refunding them. Knows nothing about bookings beyond their id.", ["shared"]),
    "booking":      ("Holds, checkout, cancellations, refund policies and booking history.",
                     ["catalog", "inventory", "payment", "pricing", "shared", "show"]),
    "notification": ("Emails and SMS, driven only by booking and payment events.", ["booking", "payment", "shared"]),
}
for name, (doc, allowed) in modules.items():
    deps = ", ".join(f'"{d}"' for d in allowed)
    open(f"{S}{name}/package-info.java", "w").write(f"""/**
 * {doc}
 */
@ApplicationModule(allowedDependencies = {{{deps}}})
package com.sumit.movieticketbookingsystem.{name};

import org.springframework.modulith.ApplicationModule;
""")
EOF
